rows["11:995845884"]="힘들어.."
rows["120:1197413870"]="고대 필기서로, 동시에 여러 시점에 존재하는 것처럼 보이는데, 그 문서는 과거와 미래를 거쳐 변합니다."
rows["120:1427922021"]="태풍과 태풍의 매혹으로 인한 피해를 % 증가시키고,"
rows["120:14860733"]="타겟을 침묵시키고, 비 플레이어 피해자 주문을 casting하는 것을 막는 것은 또한 47d에 걸쳐 중단됩니다."
rows["120:1489144430"]="목표물의 마음을 냉동으로 꺾고, 매술 방송을 중단하고 그 학교의 매술이"
rows["120:1637597467"]="@Heroic Raid@Druid은 우리 주인들을 향해 분노했지만 그의 분노는 미쳤고, 그의 미신은 그들 일부가 되었습니다."
rows["120:1672863964"]="은색 액체가 깨지지 않는 검은 껍질 속에 흐르고 있습니다. 주위로 극한의 힘의 정기가 뿜어져 나옵니다."
rows["120:1887494038"]="@|cFFCC0000피가 갈라진|r@이 벨트의 내부에 긴 면책이 새겨져 있습니다. 글은 읽을 수 없을 정도로 작습니다"
rows["120:1937260332"]="공격에 대한 다음 공포 효과는 실패하고, 방역을 사용한다."
rows["120:2060475077"]="인간과 악마, 죽은 자와 원자들에 대한 모든 피해를 추가로 증가시킵니다."
rows["120:25299445"]="친근한 목표물을 방어하기 위해 오세요. 3까지의 적들이 목표물을 공격하고 대신 팔라딘을 공격하도록 명령하세요."
rows["120:294134514"]="이 스크롤은 어떻게 사용해야 하는지 가르쳐 줄 것입니다. 2 두 손으로 사용하는 무기 , 두 가지 무기를 사용해야 한다는 것을 기억하세요"
rows["120:401720920"]="아레나 전투에서 승리로 점수를 얻습니다. 이 아레나 포인트로 멋진 상을 교환할 수 있습니다!"
rows["120:459375059"]="@미티크 레이드@ 드루이드는 우리 주인들에 대항하여 분노했지만 그의 분노는 광기에 변했고, 그의 광기는 그들 일부가되었습니다."
rows["120:518360138"]="증가 극대화 당신의 세어링과 마그마 토템의 손해 보너스 그리고 당신의 불, 얼음, 자연 마법"
rows["120:785795259"]=" ⁇ 이 심하게 공격될 확률을 줄이고, 소환된 악마가 당하는 피해를 줄일 수 있습니다."
rows["120:874328518"]="@미토스@이 에릭시어는 소수의 물 원자로 소유자를 변형시킬 것으로 전해지고 있습니다."
rows["120:884395743"]="구석 내부의 주둥이 쥬스는 작은 느린 폭발처럼 가득 차 있어"
rows["120:902791006"]="금속을 만들기 위해 피의 작업장에서 광산업자가 녹여\0101, 2 및 3 고위험 구역의 광산 노드에서 얻습니다."
rows["121:1026326126"]="당신의 Eviscerate와 Envenom 능력은 당신의 Slice and Dice 기간을 최대 5 조합 포인트로 신선할 기회를 가지고 있습니다."
rows["121:1091670984"]="이것은 미스틱 추출을 풀게 됩니다. \010\010미스틱 추출물은 미스틱 매혹성 제단을 사용하여 재조장 장비로도 얻을 수 있습니다."
rows["121:1102666693"]="@Quest: Judgement at the Eye of Eternity@이 마법의 보석은 파란 용의 눈처럼 완벽하게 형성되어 있습니다."
rows["121:1119976276"]="당신의 스톤스킨 토템에 의해 증가한 갑옷의 양을 증가시키고, 당신의 지형 토템의 냉각을 감소시킵니다 00"
rows["121:1156707723"]="스티디 샷을 던지는 동안 피해를 입은 공격의 역량을 %로 줄이고, 타격할 확률을 높인다."
rows["121:1162083510"]="기호기술 을 위한 희귀 한 잉크. 마법적 인 특성이 없지만, 전쟁 에 관한 저작 에서 사용 하기 위해 문학자 들 은 그 색채 를 추구 한다."
rows["121:1335291349"]="당신의 비시대적인 공격적 매술 크리트는 65d에 의해 극대화와 함께 공격을 받을 수있는 기회를 증가시킬 것입니다."
rows["121:1337573762"]="당신의 비시대적인 공격적 매술 크리트는 77d에 의해 극대화와 함께 공격을 받을 수있는 기회를 증가시킬 것입니다."
rows["121:1337590923"]="당신의 비시대적인 공격적 매술 크리트는 78d에 의해 극대화와 함께 공격을 받을 수있는 기회를 증가시킬 것입니다."
rows["121:1903183966"]="혈통 작업장에서 가죽 노동자가 치료하여 가죽을 만들 수 있었습니다.\010Tier 1, 2 & 3 고위험 구역에서 얻었다."
rows["121:1907233572"]="기계공학 수련을 하지 않은 초보자들을 위한 다이너마이트로 일반 초보자용 다이너마이트에 비해 위험도는 낮아졌고 폭발력은 두 배 늘어났습니다."
rows["121:1933709114"]=" ⁇ 은 알다라의 맥주 특집판으로 Azzar Faire를 위해 만들어진 맥주의 품질을 반영합니다."
rows["121:1951178970"]="셋부터 거꾸로 셉니다. 영까지 세면 자신을 때리던 적들이 싸움을 멈출 것입니다. 글쎄요, 일단 이론상으로는 그렇습니다만..."
rows["121:2023702523"]="기일드 플랜어를 설치하여 모든 플레이어가 당신의 기일드에 참여하고 상호 작용할 수 있습니다."
rows["121:208653084"]="의로운 불로 불타는 축복받은 명령이며, 부패한 자들의 마음에 두려움을 심어주기 위해 만들어진 거룩한 글입니다."
rows["121:2141210800"]="벤처기업의 표지를 들고 있는 편지. 퀘클에 가져오기 전에 직접 읽어볼 이유가 없어요."
rows["121:284540065"]="실제로 존재하지 않는 위험에 대해 경고합니다. 아직 충분히 패러노이드가 아닌 파나리오이드 모험가에게는 완벽합니다."
rows["121:543339593"]="이 세상에서 수천 개의 위험들이 널 기다리고 있어"
rows["121:730231522"]="불안한 왕의 분노가 당신을 지배하고 공격할 때 불꽃을 뱉기 시작하십시오. 이것은 화장품 효과입니다."
rows["122:1126253425"]="낚싯대를 들고만 있어도 벅찬 느낌이 전해집니다. 지금까지 본 것들 중에서 가장 놀라운 물건입니다."
rows["122:1199001828"]="화염초 꽃잎, 보라 연꽃, 아서스의 눈물, 태양풀, 실명초, 유령버섯, 그롬의 피를 제분하여 얻을 수 있습니다."
rows["122:1242048381"]="전문성을 높여 1, 그리고 모든 당과 침습 멤버를 증가합니다 전투력 한 마일 정도 떨어진 곳에 있는 샤만"
rows["122:1541894019"]="미니맥맵에서 모든 악마의 위치를 표시합니다. 한 번에 하나의 추적 형태만 활성화 될 수 있습니다."
rows["122:1588305106"]="가장자리는 찢어지고, 문장도 부서져 있습니다. 아제로스에서 어떻게 이 일이 살아남았는지 그리고 어떻게 여기까지 오게 되었는지 궁금합니다."
rows["122:1588366796"]="@|cFFCC0000 히어로 블러드포지드|r@니올otha 시에서는 많은 것들이 영원히 꿈꾸고 있습니다. 당신은 그들과 함께 할 것입니다. 모든 사람들이 그들과 함께 할 것입니다"
rows["122:1682068795"]="@미티크@무엇이든, 당신이 이걸 가지고 있는 한, 나는 당신을 찾을 수 있을 것이라고 확신합니다. 그래서 울지 않아도 됩니다, 알았어 Miel?"
rows["122:1813831354"]="알케미스트들은 이것을 혈연의 작업장에서 재료로 재배할 수 있습니다.\010\010고위험지대에 있는 허브 노드에서 얻었습니다."
rows["122:1955914224"]="발톱 지팡이, 모든 공격에 통증과 피를 극대화하도록 설계되었습니다. 적으로부터 고백을 추출하는 데 완벽합니다"
rows["122:1964280867"]="작은 회색 머리카락의 봉쇄와 라비아와 그녀의 어머니 집 정원에서 찍은 작은 그림이 담긴 메달렛"
rows["122:2006116787"]="미니메트 지도에 있는 모든 유동들의 위치를 표시합니다."
rows["122:287805353"]="흔하지 않은 위험 물질은 죽음으로 사라지지 않습니다!\010\010위험 높은 파티 로트 공유!\0102 및 3급 고위험지역에서 얻었다."
rows["122:375774977"]="안전한 지역에서 휴대용 은행처럼 행동하는 이 동반자를 불러내는 방법을 가르쳐줍니다.\010\010이건 전투가 아닌 동반자입니다."
rows["122:450792331"]="@Heroic@무엇이든, 당신이 이걸 가지고 있는 한, 나는 당신을 찾을 수 있을 것이라고 확신합니다. 그래서 울지 않아도 됩니다, 알았어 Miel?"
rows["122:538024585"]="목표 무기에 적용되는 동안 주기적인 매화로 인한 피해를 증가시키고 1 시간 동안 Lasts에 의해 매화 속속 등급을 증가시킵니다."
rows["122:549236750"]="@Ascended Raid@드루이드는 우리 주인들을 향해 분노했지만 그의 분노는 미쳤고, 그 미쳤던 것은 그들 일부가 되었습니다."
rows["122:855672958"]=" ⁇ 이오, 바치스에게 불리러 가르쳐줘\010\010이건 전투가 아닌 동반자입니다."
rows["122:989521887"]="극대화의 손해 보너스를 증가시킵니다."
rows["123:1031225859"]="사용에 대해 지능 (랭크 3) 를 가르칩니다.\010\010|cFFFFCC00지능:|r\010|cFFFFFFFF급 3|r\010지능을 |cffFF99003|r로 증가시킵니다."
rows["123:1132854591"]="사용에 대해 지능 (랭크 2) 를 가르칩니다.\010\010|cFFFFCC00지능:|r\010|cFFFFFFFF급 2|r\010지능을 |cffFF99002|r로 증가시킵니다."
rows["123:1234483323"]="사용에 대해 지능 (랭크 1) 를 가르칩니다.\010\010|cFFFFCC00지능:|r\010|cFFFFFFFF급 1|r\010지능을 |cffFF99001|r로 증가시킵니다."
rows["123:1329413752"]="흔하지 않은 위험 물질은 죽음으로 사라지지 않습니다!\010\0101, 2 및 3 고위험 구역의 허브 노드를 수집하여 얻었습니다."
rows["123:134201245"]="@Heroic Raid@Aydreath는 자신을 자연의 귀한 보호자라고 믿었지만 결국은 평범한 짐승이었습니다."
