rows["142:1774329560"]="@|cFFCC0000 히어로 블러드포지드|r@Aydreath는 자신을 자연의 귀한 보호자라고 믿었지만 결국은 평범한 짐승이 아니었다."
rows["142:1833126525"]="동시에는 토템 바에 지정된 최대 4 도테임을 배치합니다. 원소 또는 조상들의 호출보다 다른 토테임을 호출할 수 있습니다."
rows["142:1842130989"]="@세계벼림이 고대 리라에서 부드럽고 멜로디적인  ⁇ 이 울려 퍼져 있습니다."
rows["142:1909657775"]="활성화되면 다음 매기의 마나 비용을 줄이고, 만약 중요한 효과를 낼 수 있다면 그 결정적인 효과의 가능성을 높일 수 있습니다."
rows["142:550916408"]="@Ascended Raid@이 토큰은 Tier 6 Bracer 슬롯 아이템에 대한 글로벌 토큰입니다. 당신은 이 상위에서 찾을 수 있습니다 6 선웰 섬에서 발견 판매자."
rows["142:561141124"]="@Tier 20@\010이 도끼에게 분노를 준 불은 화로 변해버렸어 이제 그것은 냉정하고 인내하며,"
rows["142:703014528"]="제가 변화시킬 수 없는 것을 받아들일 힘과, 제가 변화시킬 수 있는 것을 바꿀 수 있는 용기와, 차이를 구별할 줄 아는 지혜를 주소서."
rows["142:727731055"]="캐릭터 진전에서 주문 아이콘을 클릭하여 주문을 배워내기 위해 사용되었습니다.\010\010와일드카드 모드 및 드래프트 모드에서 재능을 사용할 수 있습니다"
rows["142:872419262"]="얼음 현존 또는 불성스러운 현존에서, 당신은 혈액 현존으로부터 치유를 유지하며, 당신에게 치료가 이루어지는 것은 혈액 현존에 의해 증가합니다."
rows["143:103859048"]="당신의 파괴적인 폭발파와 용의 호흡 마법을 통해 다음 플라메스트라이크 마법을 즉시 cast 할 수 있습니다 마나- 마지막 41d."
rows["143:1208843894"]="마법소녀에서 미스틱 매춘 전문성을 열 수 있는 도구로 사용된다. 다른 플레이어, 경매소, 또는 잃어버린 가게에서 얻을 수 있다."
rows["143:1400510916"]="에로르타 노 샤드라의 상징인 거미의 영적 본질. 어떤 사람들에게는, 스파이더 로아가 운명과 속임수를 구현하고 있다. 다른 사람들에게는 살인과 속임수를 의미한다."
rows["143:1744595616"]="더 큰  ⁇ 핵의 파편된 조각으로, 이 껍데기는 휘발성 힘으로 빛납니다. 그 안에서의 악마적 에너지는 그 주변의 공기 자체를 왜곡합니다."
rows["143:1773994448"]="당신이 그 영혼을 배출하는 동안 목표물이 죽으면 최대의 마나을 반환합니다. 또한, 당신의 고통 주문은 위협이 덜 발생합니다."
rows["143:1905505517"]="반려동물의 통제력을 상실하는 모든 운동 장애와 영향을 제거하고 반려동물에 발생한 손상을 96d로 줄입니다."
