rows["143:391828314"]="혈연의 작업장에서 화학자가 재배하여 재료들을 만들었죠.\010Tier 1, 2 & 3 고위험 영역에서 허브 노드를 수집하여 얻었습니다."
rows["143:433161975"]="고대 마법소녀 제단을 지탱하는 힘의 대상이야"
