rows["143:844294128"]="3토템 마을의 군인으로부터의 갑옷 조각. 얼마 전, 그 착용자는 몰고름 홀로후프라는 타이랑과 전투에서 쓰러졌습니다."
rows["143:970016494"]="두 손으로 하는 동전 무기를 영구적으로 매료시키는 방법을 가르쳐줍니다 9레벨이 필요합니다 30 이 혜택을 얻기 위해"
rows["144:1086890777"]="반려동물이 죽이는 광기에 빠집니다. 성공한 공격은 증가할 가능성이 있습니다 전투력 이 효과는 시간으로 쌓이게 됩니다. 01d."
rows["144:1093048522"]="자동샷으로 피해를 입는 동안 추가로 쏠 수 있는 기회가 있습니다. 자연 피해와일드 키버는 탄약을 사용하지 않는다."
rows["144:1117180689"]="친절 한 목표 를 축복 으로 부리고, 증가 합니다 전투력 플레이어는 한 번에 팔라딘당 하나의 축복만 받을 수 있습니다."
rows["144:1184252253"]="이 캐시는 소수 프로파네 에센스를 포함하고 첫 번째 발사 발매 시 해당 아이템 레벨에 따라 가짜 혈액을 보상합니다."
rows["144:1185878925"]="@|cFFCC0000영웅적 인 피가 만들어졌어요|r@금속은 촉각에 따뜻하다. 벨트를 연결하는 링크는 에레멘티움으로 만들어졌다고 보입니다."
rows["144:14084963"]="@|cFFCC0000피가 갈라진|r#비생충의 두개골이 이제 칼 위에 있습니다. 도끼 머리 위로 피를 새겨져 있는 한 단어로 10번 반복됩니다: 고통"
rows["144:1592753543"]="당신의 배스타브 및 함정에 대한 에너지 비용을 감소시키고, 당신의 출혈의 에너지 비용을 2, 그리고 모든 손상으로 증가합니다."
rows["144:1638749076"]="밤새처럼 어두운 당신의 템드 에본코일을 장착합니다. 당신의 어깨에서 지켜보는 조용하고 그림자 같은 동반자가 당신의 길을 감시하고 있습니다."
rows["144:1693169965"]="모든 팀원에게 추가적인 불 저항을 제공하고 야드 내에서 침습 구성원을 제공합니다. 플레이어는 한 번에 팔라딘당 하나의 아우라를 가질 수 있습니다."
rows["144:182014747"]=" ⁇ 터 발에 건강이 있는 윈드피리 토템을 불러주며, 모든 파티 구성원들에게 모순의 서둘러서"
rows["144:1995061637"]="이 가방에는 모든 순수품이 들어있어요!\010이 가방을 열면 재능과 능력의 순결과 3개의 언러닝 스롤이 포함되어 있습니다!"
rows["144:2000150973"]="고르도크 오그로 변신해, 심지어 어떤 캡틴을 속일 수도 있어! $d1."
rows["144:2005964259"]="이 기호에서 뒤틀린 황천 폭풍의 눈의\010치료와 마나 투여는 전투에서 다른 투여와 분리된 냉각을 위해 사용될 수 있습니다."
rows["144:2116734869"]="당신의 Imp, Voidwalker, Succubus, Felhunter 및 Felguard의 체력 및 지능을 증가시키고 당신의 최대 건강과 마나를 증가시킵니다."
