rows["144:274699818"]="당신의 얼음 발사, 얼음 랜스, 깊은 얼음 및 블리자드 마법을 확장하고"
rows["144:313591688"]="스타파이어, 히버네이트, 허리케인 등이 공격에 의해 발생했던 역량을 줄이고"
rows["144:468757460"]="@세계벼림@이 지역 비참한 사람들은 한때 빛를 따르기도 했지만, 그들의 몸과 마음이 깨져있어서 그들의 가르침은 오래전부터 잊혀졌다."
rows["144:589349375"]="브롤러스 길드의 우승자에게 수여됩니다. 브롤러스 골드 거래소에서 럼블 카드 및 다른 세계를 변화시키는 아이템을 구입하는 데 사용하십시오."
rows["144:738221101"]="@히로이크 검은날개 둥지@ 은 액체는 침투 불가능한 에본 상껍질 안에 흐른다. 이 물체는 순수하다고 느껴집니다. 그것은 극도의 힘을 방사합니다."
rows["144:820152673"]="당신의 마나 정신의 재생은 플래시 치유, 더 큰 치유, 결합 치료 또는 강화된 재생으로 비평적으로 치유 된 후에 증가합니다."
rows["144:95893063"]="드레인 라이프, 드레인 마나, 드레인 소울, 불안한 고통, 그리고  ⁇ 트 마법을 캐스팅하면서 피해를 입힌 공격으로 인한 반격을 줄입니다."
rows["145:1443494617"]="의심스러운 용도로 사용된  ⁇ 돌이 된 기구인데,  ⁇ 돌고 있는 배럴과 비슷합니다."
