rows["145:1919810270"]="이산드 검은날개 둥지@이번드레스 껍질 안에 은 액체가 흐르고 있습니다. 이 물체는 순수합니다. 그것은 극한의 힘을 방사합니다."
rows["145:1927002650"]="신성 피해에 대해 처리하는 적에게 성스러운 방패를 던지고, 그들을 놀라게 하고 그리고 더 가까운 적들에게 뛰어드는. 전체 목표물에 영향을 미칩니다."
