rows["153:6254826"]="@Ascended Raid@이 토큰은 계층 6 어깨 슬롯 항목에 대한 글로벌 토큰입니다. 이것은 시간의 동굴 (Hyjal 정상) 에서 발견된 판매자에서 교환됩니다."
