rows["154:1031963721"]="사라지는 것 마나 이 조각은 놀랍도록 친근한 마나 그 성품은 사랑스러운 성격에도 불구하고 다른 사람들과 같은 운명을 맞았다."
rows["154:1065880744"]="뱀 의 영적 본질, 다મ્બ라 의 상징. 어떤 사람 들 에게는 뱀 로아 는 지혜 와 음모 를 구현 한다. 다른 사람 들 에게는 그 은 배신 의 표징 이 된다."
rows["154:1096026588"]="@Classic@Classic Raids에서 얻었습니다. 수도권에서 발견된 Romus the Redeemer로부터 장비를 구입할 수 있습니다. 경비원들은 Romus의 방향을 알려줄 수 있습니다."
rows["154:1224254996"]="이 악의 에릭시어는 음주자에게 큰 힘을 주지만 그 대상은 흑색한 영혼입니다."
rows["154:1438364425"]="마나폭풍에서 얻어진 수준: 511에서 535\010포함하고 있습니다. \010+ 미틱 검은날개 둥지 기어\010+ AQ 기어의 정상적인 유해\010포함 가능성은: \010+ 미틱 11-20 던전 기어"
rows["154:539650372"]="이 거대한 절단된 머리는 한때 그루울의 아들 중 가장 잔인한 그루롤의 어깨 위에 앉아 있었습니다. 그 빈 사이클로프 시선이 여전히 원시적인 야만성을  ⁇ 니다."
rows["154:554531027"]="워크라이브는 주인들의 죽음으로 모든 힘을 잃었습니다. 래디 바쉬나 카엘타스 선스트라이더의 손상되지 않은 유통과 함께 그 힘을 회복합니다."
rows["154:788677445"]="이 책은 쟁이한 낭만 소설처럼 보입니다. 표면에는 근육질의 금발 한 남자와 긴장한 몸옷을 입은 젊은 여성과 관련된 목회 장면이 있습니다."
rows["154:827322419"]="여러 굵은 선과 일련의 명령들과 함께 알레리아 성채와 돌망치 요새의 위치가 정확하게 표시되어 있습니다."
rows["154:982501075"]="@Heroic@Naaru G'eras는 정의의 표지를 영웅 기어 또는 다른 정의의 표지를 보상으로 환불할 수 있습니다."
rows["154:982728568"]="@미토스@나아루 게라스는 정의의 표지를 영웅 기어 또는 다른 정의의 표지를 보상으로 환불할 수 있습니다."
rows["155:1018201829"]="노즈도르무는 더 이상 이 손상된 장신에 유용하지 못해, 어쩌면 당신 같은 영웅이 사용할 수 있을 것 같군요."
rows["155:1022873869"]="@세계벼림무르락의 혁신적인 발자국으로 만든  ⁇ 소리 스냅퍼의 치아에서 만들어진"
