rows["165:826333701"]="@Ascended Raid@이 토큰은 Tier 4 Chest Slot 아이템에 대한 글로벌 토큰입니다. 당신은 이것을 Shattrath의 Scryer 또는 Aldor Tier 내에 발견되는 모든 Tier 4 벤더로 변환할 수 있습니다."
