rows["165:906206917"]="식병으로 인한 주기적인 피해를 %로 증가시키고, 식병을 던지면 그 전체 주기적 효과와 동등한 피해를 즉시 발생시킵니다."
rows["165:930553402"]="빛의 번개, 거룩한 빛 또는 신성한 충격 치유 마법을 통해 중요한 효과를 얻으면 마사의 기본 비용과 동등한 마나을 얻을 수 있습니다."
rows["166:1078597307"]="이 혈액은 불타는 군단의 수많은 악마들의 결합된 펠 본질과 함께 흐른다. 이 작은 복용량에도 불구하고, 우주적 부패는 그 주변의 현실을 침투한다."
rows["166:1162040820"]="리치 왕@ 'A Thin Line', 'Making Ends Meat', 'Wrapping Things Up' 콜보드 퀘스트를 완료합니다.\010\0106보다 적은 재고 슬롯을 사용할 수 있는 경우 사용하지 마십시오."
rows["166:1166668058"]="@Ascended Raid@이 토큰은 Tier 4 장갑 슬롯 아이템의 글로벌 토큰입니다. 당신은 이것을 Shattrath에서 Scryer 또는 Aldor Tier 내에 발견되는 모든 Tier 4 판매자로 변환 할 수 있습니다."
rows["166:1632129054"]="해로운 공격이 건강을 떨어뜨리면, 당신의 건강은 증가하고 공격자에 대한 위협 수준도 감소합니다.  30 두 번째 냉각."
rows["166:1652528451"]="당신의 템드 베르던트 코일을 장착합니다. 야생과 원활하게 섞여서 수호자 숲의 그림자 속에 빠져들기 위해 항상 준비되어 있습니다."
rows["166:1761529737"]="당신의 동행 공격은 다음 아이스 터치, 우는 폭발 또는 얼음 스트라이크를 극대화 할 수있는 기회를 가지고 있습니다. 효과는 킬링 머신 (랭크 1) 보다 자주 발생합니다."
