rows["166:1761581220"]="당신의 동행 공격은 다음 아이스 터치, 우는 폭발 또는 얼음 스트라이크를 극대화 할 수있는 기회를 가지고 있습니다. 효과는 킬링 머신 (랭크 4) 보다 자주 발생합니다."
rows["166:1772570051"]="그 안에 있는 에너지를 느낄 수 있고 거의 마치 어딘가에 끌고 가는 것 같죠. 너무 희미하고 빠르게 사라지고 있지만, 더 가까이 있다는 것을 느낄 수 있습니다."
rows["166:259272212"]="@Mythic Raid@이 토큰은 Tier 5 Shoulder Slot 아이템에 대한 글로벌 토큰입니다. 당신은 이것을 Shattrath의 Scryer 또는 Aldor Tier 내에 발견되는 모든 Tier 5 벤더로 변환 할 수 있습니다."
rows["166:321838567"]="무기 손상으로 두 무기를 동시에 공격하고, 각각의 무기로 추가적으로 공격합니다. 20독성 대상자에 대한 대상은 2 복합점"
rows["166:574775986"]="모든 스턴 효과의 기간을 더 많이 줄이고 도움이 되는 마법과 시간이 지남에 따라 손상되는 효과를 더 많이 없애는 확률도 낮아집니다"
rows["166:727190685"]="태양빛의 감독자를 불러라, 안 ⁇ 셰 ⁇ 의 빛나는 시선이 네 길을 밝게 해라. 새벽처럼  ⁇ 은 깃털로 이 경호한 수호자이 너의 모든 걸음을 지켜보고 있다."
rows["166:834452169"]="메레의 공격에 대해 모순적으로 공격하는 적을 즉시 반격하십시오. 뒤에서 공격을 할 수는 없습니다. 최대 공격은 복수력을 유발합니다."
rows["166:850365979"]="귀신들의 영역에서 발견한 이상한 존재가 당신에게 준 에메랄드 드림의 조각이 그 힘을 이용해서 과거의 기억을 목격할 수 있게 해줍니다."
rows["166:905194825"]="@Ascended Raid@이 토큰은 Tier 5 장갑 슬롯 아이템의 글로벌 토큰입니다. 당신은 이것을 Shattrath에서 Scryer 또는 Aldor Tier 내에 발견되는 모든 Tier 5 판매자로 변환 할 수 있습니다."
rows["167:1499910456"]="공격 을 피하거나 마법 을 완전히 저항 한 후 목표 에 콤보 포인트를 추가 할 수 있는 기회 를 제공합니다. 이것은 초당 한 번 이상 일어나지 않습니다."
rows["167:195414058"]="@Heroic Raid@ 이 토큰은 레벨 4 어깨 슬롯 항목에 대한 글로벌 토큰입니다. 당신은 이것을 스캐어 또는 알도르 레벨에서 발견되는 모든 레벨 4 판매자로 변환 할 수 있습니다."
rows["167:1997223123"]="사전 주문 지원자 상자는 업데이트되었습니다. 업데이트 전에 미리 주문했기 때문에, 당신은 원래 패키지와 새로운 것을 받고 있습니다!"
rows["167:2101571559"]="|cff00ffff 이것은 당신이 아이템 레벨 105 pvp 세트 중 다양한 선택 할 수 있게 해줍니다.\010\010이 항목은 Outlandish Felforged Provisions에 따라 소비자 보조 장비 1 집합이 됩니다|r"
rows["167:304460541"]="당신은 부상당한 목표를 제거하려고 시도하고, 장거리 공격을 발사하여 무기 피해를 더해  ⁇  총은 오직 20% 또는 그 이하의 건강이 있는 적에만 사용될 수 있습니다."
rows["167:38079543"]="진정한 블래드마스터의 깃발은 단순히 바람을 따라가지는 않습니다. 전투의 리듬과 함께 움직입니다. 철 폭풍 속에서 춤추는 붉은 유령입니다."
rows["167:592751295"]="이 산이 날 수 있는 모습으로 변하는 법을 가르쳐줍니다\010\010달릴 수 없을 때,  ⁇ 을 걸고,  ⁇ 을 할 수 없을 때, 당신을 지탱할 사람을 찾습니다."
rows["167:654102320"]="적의 목표물을 잠들게 해주는 것은 모든 손상이 목표물을 깨우치게 하는 것입니다. 한 번에 한 목표물이 hibernate 할 수 있습니다."
rows["167:698020110"]="잊혀진 광산 탐험가의 기록으로, 당신이 그와 이야기하기 위해 머물렀다면 노인이 말한 것과 같은 이야기라고만 가정할 수 있습니다."
rows["167:729194923"]="영원히 굶주리고, 영원히 잔인한 이 비참한 두개골은 죽은 사람들을 자기 주인에게 유혹할 암울한 약속을 속삭였다"
rows["167:855748152"]="@Burning Crusade@ 최대 레벨을 열어야 하며, 다음을 포함합니다:\010 - 기어 네 타입에 따라 선택 가능해\010 - 당신이 열었던 글로벌 계층 토큰 하나 이상의 가능성이 있습니다."
