rows["168:98853489"]="성 에너지의 폭발이 캐스터를 채우며, 각 부대 또는 사제에게 당한 피해는 한 가지 충격을 제거합니다."
rows["169:1265450723"]="토테마는 힘과 힘을 증가시켜 민첩성 라스트의 영위권에서"
rows["169:1707157586"]="거북이의 수많은 품종 중 한 개의 잔해입니다. 두 개는 자연적으로 포식자이지만, 거북과 고래는 서로 가장 격렬한 적을 알아봅니다."
rows["169:1926334480"]="사용에 대해 레베스트 (그룹) (랭크 5) 를 가르칩니다.\010\010|cFFFFCC00수확 (그룹):|r\010|cFFFFFFFF급 5|r\010당신의 그룹은 |cffFF990010%|r 두 번째 동물들을 도난시킬 기회"
rows["169:1976018256"]="근처에 있는 적들이 공격하는 동안의 시간을 늘리고, 피해를 입히게 됩니다. 전투력이 능력은 추가적인 위협을 야기합니다."
rows["169:2106015120"]="이 친구를 불러내는 법을 가르쳐줍니다.\010\010상승의 책에서는 모든 능력을 훈련시킬 수 있습니다\010\010시즌 4\010\010이건 전투가 아닌 동반자입니다."
