rows["169:224778400"]="이 친구를 불러내는 법을 가르쳐줍니다.\010\010상승의 책에서는 모든 능력을 훈련시킬 수 있습니다\010\010시즌 2\010\010이건 전투가 아닌 동반자입니다."
rows["169:523513510"]="죽음 기사에게 피를 공급하여 힘을 주며, 한 번에 하나의 존재만 활동할 수 있습니다."
