rows["170:164356998"]="1 질병과 1 독효과를 제거하는 시속당의 구성원으로부터 모든 세컨트리 내에 제거하려는 투터 발에 건강있는 청결 토템을 소환합니다."
rows["170:1771175949"]="증가 극대화 또한, 당신의 소멸자가 질병을 섭취하지 않고도 피해를 입힐 가능성이 있습니다."
rows["170:1971523075"]="한 손에 두손의 축, 막대기 및 검을 장착할 수 있습니다. 한 손으로 두손의 무기를 장착하는 동안, 당신의 물리 피해 완료는 52s1% 감소합니다."
