rows["171:1034421800"]="@Heroic Raid@이 토큰은 Tier 1 Leg Slot 항목의 글로벌 토큰입니다. 이것은 스톰윈드 (Major Mattingly) 또는 오그리마 (Overlord Runthak) 에서 발견된 벤더에서 교환 가능합니다."
rows["171:1105099844"]="당신의 주문 비판은 다음 Smite 또는 Flash Heal 주문이 즉시 캐스팅 될 수있는 기회를 가지고 있습니다, 비용 마나 하지만 비판적 인 타격을 할 수 없습니다. 이 효과는 51d 지속됩니다."
rows["171:1225895134"]=" ⁇ 이 공격 속도를 더 길게 증가시키는 완결 동작:\010   1 점: 초\010   2 점: 초\010   3 점: 초\010   4 점: 초\010   5 점: 초"
rows["171:1544434441"]="오른쪽 클릭!\010\010클래스를 선택하고 수신:\010- 순찰자의 옷\010- 나무의 깃발 잎\010- 나무 깃털의 대구\010- 에메랄드 판다렌 피닉스의 리인"
rows["171:1682072418"]="@Classic@이 임시상들은 티라크시스 에테럴 바자르에서 또는 크롬리에서 금으로 바자르 토큰을 사용하여 구입할 수 있습니다.\010\0106보다 적은 재고 슬롯을 사용할 수 있는 경우 사용하지 마십시오."
rows["171:2000040686"]="@Heroic Raid@이 토큰은 폐지되었으며, 이제 상승의 모든 계층 토큰은 글로벌 토큰입니다. 만약 당신이 생물로부터 이것을 받았다면, 버그트랙러 보고서를 열십시오."
rows["171:2020425817"]="극대화 혈중, 스컬지 심장마비 및 폐간의 확률을 %로 증가시키고, 혈액이나 불성스러운 존재 중에 발생되는 위협을 감소시킵니다."
rows["171:2020530855"]="@Heroic Raid@이 토큰은 Tier 2 Leg Slot 항목의 글로벌 토큰입니다. 이것은 스톰윈드 (Major Mattingly) 또는 오그리마 (Overlord Runthak) 에서 발견된 벤더에서 교환 가능합니다."
rows["171:2092138962"]="@Mythic Raid@This Token 는 Tier 1 Leg Slot 아이템에 대한 글로벌 토큰이다. 이것은 스톰윈드 (메이저 매팅리) 또는 오그리마 (오버로드 러닝타크) 에서 발견된 벤더에서 교환 할 수 있습니다."
rows["171:594685987"]="이 친구를 불러내는 법을 가르쳐줍니다. \010\010탐욕적인 괴물은 높은 위험의 물건들을 보호하기 위해 휴대용 Fel-커무팅에 접근할 수 있게 해줍니다\010\010이건 전투가 아닌 동반자입니다."
rows["171:891801390"]="한눈에 볼 때, 발레시르 경은 \"아르고스 웨이크\"라는 그룹과 함께 정변을 계획하는 신디케이트 지도자와 협력하고 있는 것 같습니다."
rows["171:930764370"]="@Mythic Raid@This Token 는 Tier 2 Leg Slot 아이템에 대한 글로벌 토큰이다. 이것은 스톰윈드 (메이저 매팅리) 또는 오그리마 (오버로드 러닝타크) 에서 발견된 벤더에서 교환 할 수 있습니다."
rows["171:994332300"]="배수와 백스태브 공격은 목표물을 불균형화시킬 수 있고, 전투와 거리의 공격 사이의 시간을 %로 늘리고, 이동 속도를 93d로 줄일 수 있습니다."
