rows["179:1251192258"]="지구결합 토템의 발동은 또한 당신과 가까운 친근한 목표에서 모든 함정 효과를 제거할 수 있는 기회를 가지고 있습니다. 그리고 당신의 지구 충격은 적 공격 속도를 추가로 줄여줍니다."
