rows["180:487854273"]="@Ascended Raid@이 토큰은 레벨 2.5 어깨 슬롯 항목에 대한 글로벌 토큰입니다. 이것은 스톰윈드 (마저 매팅리) 또는 오그리마 (오버로드 러닝타크) 에서 발견된 판매자에게 교환 할 수 있습니다."
rows["181:217003279"]="엘룬이 숨길 수도 있는 것처럼 빛 태양의 빛은 어둠의 별이 꿈에 의해 은폐되었다는 것과 같습니다.\010하지만 가장 긴 행식은 우주 역사의 짧은 순간일 뿐이죠"
rows["181:410210465"]="프리스킬라의 유일한 슬픈 헝가리에서 막상 조각을..."
rows["182:1370115650"]="보너스 마크, 오브, 루나, 레이더 등등을 포함할 수 있는 기회도 있습니다.\010\010개인 로트는 당신이 선호하는 기기 유형에 대한 습격에서 기기를 선택할 수 있습니다."
rows["182:1878299380"]="미스터스 (Stealthed) 로 작동해야 한다. 전투에 있지 않은 휴마노이드에서만 작동한다. 발생한 모든 손상은 목표를 다시 살려줄 것이다. 한 번에 1 목표만  ⁇  수 있다."
rows["182:1954842632"]="엔드게임 마나스타머스에서 얻은 |cffFFFFFF수준 106 레벨 136.|r\010\010|cFFffffff내용:|r \010\010+ 영웅적인 던전 기어\010\010|cFFffffff 포함 가능성은:|r\010\010+ 정상적인 카라잔 기어"
rows["182:1967963019"]="화염병의 마법을 더해주는 것 , 그리고 지구생들의 치료 효과를 증가시키는 것"
rows["182:504194910"]="에레멘탈 포커스의 클리어캐스팅이 활성화되면서 더 많은 주문 피해를 입히게 됩니다. 또한, 야드 내에 있는 파티와 레이드 멤버들은 그들의 주문 극대화 기회에 보너스를 받는다."
rows["182:8582563"]="추가 %로 회피할 확률을 높이고, 당신에게 대항하여 사용된 모든 Disarm 효과의 기간을 줄입니다."
rows["182:977314013"]="이 문장에는 법적으로 구속력이 있습니다. 은유적으로 말하자면, 이 문장에서는 많은 가치를 얻었습니다. \010\010비밀, 표지되지 않은 무덤, 또는 경쟁적인 정원을 파헤치는데 좋은 방법"
rows["183:1103795998"]="당신의 공격이 피되는 가능성을 줄이고, 당신에게 대항하여 사용된 모든 Disarm 효과의 기간을 줄이는 것이 다른 Disarm 지속을 줄이는 효과와 함께 쌓이지 않습니다."
rows["183:1160985541"]="레지온파일 (그룹) (랭크 2) 을 사용하도록 가르칩니다.\010\010|cFFFFCC00레지온포스 (그룹):|r\010|cFFFFFFFF급 2|r\010당신의 그룹은 레지온 캐시로부터 추가적인 약물을 얻을 수있는 |cffFF99004% |r 기회를 가지고 있습니다."
rows["183:1485055242"]="레지온파일 (그룹) (랭크 1) 을 사용하도록 가르칩니다.\010\010|cFFFFCC00레지온포스 (그룹):|r\010|cFFFFFFFF급 1|r\010당신의 그룹은 레지온 캐시로부터 추가적인 약물을 얻을 수있는 |cffFF99002% |r 기회를 가지고 있습니다."
rows["183:1555726617"]="얼음 함정 및 냉동 함정 - 함정, 폭발 함정 및 검은 화살의 기간을 증가시킵니다"
rows["183:1602121515"]="@Burning Crusade@이 임시들은 티라크시스 에테럴 바자르에서 또는 크롬리에서 금으로 바자르 토큰을 사용하여 구입할 수 있습니다.\010\0106보다 적은 재고 슬롯을 사용할 수 있는 경우 사용하지 마십시오."
rows["183:1659137988"]="트랜스모그리피케이션에 대한 화장품 세트. 당신은 화장품 세트를 보실 수 있습니다. 만티 컬렉션에서 볼 수 있습니다. 이 다른 플레이어, 경매소, 또는 잃어버린 가게에서 얻을 수 있습니다."
rows["183:2100051700"]="이 산을 불러내는 법을 가르쳐줍니다. \010\010부드럽고 달콤하고 항상 옆에 있어 램러가 네가 타고 다니는 가장 푹신한 친구야"
rows["183:343690429"]="마법의 피해를 줄이고, 적을 때 신성  ⁇ 이 지속되는 기간을 새롭게 할 수 있는 기회를 줍니다. 또한, 신성  ⁇ 은 약화가 덜 가능하죠."
rows["183:512846139"]="레지온파일 (그룹) (랭크 4) 을 사용하도록 가르칩니다.\010\010|cFFFFCC00레지온포스 (그룹):|r\010|cFFFFFFFF급 4|r\010당신의 그룹은 레지온 캐시로부터 추가적인 약물을 얻을 수있는 |cffFF99008% |r 기회를 가지고 있습니다."
