rows["184:1109109213"]="레지온파일 (그룹) (랭크 5) 을 사용하도록 가르칩니다.\010\010|cFFFFCC00레지온포스 (그룹):|r\010|cFFFFFFFF급 5|r\010당신의 그룹은 레지온 캐시로부터 추가적인 약물을 얻을 수있는 |cffFF990010% |r 기회를 가지고 있습니다."
rows["184:838528851"]="방어적인 자세에서 모든 주문 손상은 감소하고 당신이 차단, 파리 또는 도지 공격에 의해 물리 피해 이 때문에 14d."
rows["184:838563173"]="방어적인 자세에서 모든 주문 손상은 감소하고 당신이 차단, 파리 또는 도지 공격에 의해 물리 피해 이 때문에 16d."
rows["185:1117842916"]="당신의 Imp에 의해 인한 피해를 %로 증가시키고, 당신의 Imp에 의해 이루어진 모든 중요한 타격은 다음 매기에 대한 마법의 비판적 타격 기회를 증가시킬 수 있습니다. 이 효과는 83d까지 지속됩니다."
rows["185:1183912582"]="이 약물은 신성 방패, 신성 보호 또는 보호 손의 대상인 경우 사용되지 않습니다."
rows["185:127017483"]="대상을 저주하는 데, 아카네, 불, 얼음, 자연, 그림자 저항을 줄이고 마법의 손상을 증가시키는 데"
rows["185:1829188011"]="당신의 불태우와 혼란의 발트 매술로 인해 당한 목표에 대한 피해를 % 증가시키고, 당신의  ⁇ 화 매술의 확률은 극대화 증가합니다."
rows["185:1996082599"]="@|cFFCC0000피가 갈라진|r@이 유물은 마법의 광경을 내는 보라색 루니로 장식되어 구매자에게 매우 가치있는 것 같습니다. 아니면 아마도 당신은 그 힘을 스스로 활용할 방법을 찾을 수 있을까요?"
rows["185:2003301497"]="@|cFFCC0000영웅적 인 피가 만들어졌어요|r@이 장갑에 손을 넣을 때 척추를 통해 차가운 추위가 지나갑니다. 그들은 많은  ⁇ 털의 피부로 만들어졌다고 보입니다."
rows["185:59465799"]="경험이나 명예를 가져다주는 목표를 죽인 후 당신의 영에게 보너스를 얻을 기회를 제공합니다. 마나 캐스팅 중 재생속률을 높일 수 있습니다. 71d."
rows["186:1004815649"]="@|cFFCC0000Bloodforged|r@이 토큰은 Tier 2.5 링 슬롯 아이템의 글로벌 토큰입니다. 이것은 스톰윈드 (메이저 매팅리) 또는 오그리마 (오버로드 러닝타크) 에서 발견된 벤더에서 교환 할 수 있습니다."
rows["186:1218583750"]="@세계벼림@감독 몰토리우스 도구 컬렉션에서 직접. 이것은 이 발굴지를 시작한 최초의 골렘을 만들었습니다. 때로는 도구보다 더 많은 것으로 나타납니다."
rows["186:1261014878"]="치료된 양은 처음에는 빠르게 적용되며, 야생 성장이 전체 기간에 도달하면 느려집니다."
rows["186:133088393"]="활성화되면 %로 파리 확률을 높이고, 공격이 당신에게 닿는 확률을 줄이고, 주문을 돌리는 기회를 제공합니다."
rows["186:1377670095"]="화염 장군과 얼음 장군의 주문이 활동 중 보호된 주문을 반영할 기회를 갖게 합니다. 또한, 녹은 갑옷은 50%의 확률로 범위 및 주문 공격에 영향을 미칩니다."
rows["186:1844689382"]="@|cFFCC0000Bloodforged|r@이 토큰은 Tier 2.5 헤드 슬롯 아이템에 대한 글로벌 토큰입니다. 이것은 스톰윈드 (메이저 매팅리) 또는 오그리마 (오버로드 러닝타크) 에서 발견된 벤더에서 교환 할 수 있습니다."
rows["186:1881469359"]="마나폭풍에서 얻어진 수준: 476에서 510\010포함하고 있습니다. \010+ 영웅적 검은날개 둥지 기어 (1-2)\010포함 가능성은:\010+ 미틱 검은날개 둥지 기어\010+ 상승 오닉시아 기어\010+ 미틱 11-20 던전 기어"
rows["186:1905281605"]="이 책 은 붉은십자군의 역사 를 전면 히 기록 하고 있으며, 그 법령, 규정 및 의식 과 함께 조직 의 회원 들 의 완전 한 명목 을 포함 한다."
rows["186:196870336"]="이 산이 날 수 있는 방법을 가르쳐줍니다\010\010에메랄드 드림의 그로브 워든들은 악몽의 부패한 영향에 가장 먼저 휘말렸다."
rows["186:1983775715"]="중요한 공격으로부터 친근한 표적을 보호하고, 그 목표물에 대한 공격은 결정적인 공격이 될 수 없도록 하는 반면, 그 목표물이 입은 모든 피해는 애완 동물도 차지한다."
rows["186:587881110"]="V 전문으로 전환할 수 있는 기회를 해제하고 추가 미스틱 매혹적인 전문성을 해제합니다.\010\010경매소, 명예, 시장 토큰 또는 가게에서 사용할 수 있습니다."
rows["186:647557652"]="아카네 폭발의 기회를 제공합니다. 그리고 아카네 방대, 불구, 얼음발트 및 얼음불 발트는 다음 아카네 미사일 주문의 채널 기간을 00로 줄일 수있는 기회를 제공합니다."
rows["186:663747373"]="@|cFFCC0000Bloodforged|r@이 토큰은 Tier 2.5 목 슬롯 아이템의 글로벌 토큰입니다. 이것은 스톰윈드 (마저 매팅리) 또는 오그리마 (오버로드 러닝타크) 에서 발견된 판매자에서 교환 할 수 있습니다."
