rows["191:2012237395"]="이 토큰은 글로벌 프로그레시션 1 롤터 토큰입니다. 이것은 스톰윈드 (쿼터마스터 하드윈), 오그리마 (Warbringer Krogash) 또는 부티 베이 (Zazzle Refitwick) 에서 발견된 판매자에서 교환 할 수 있습니다."
