rows["191:339298214"]="당신의 극대화 모든 마법과 함께 확률이 증가하고 당신에게 대한 비판적인 공격은 당신이 자연 완벽 효과를 줄이고 82d."
rows["191:339315375"]="당신의 극대화 모든 마법과 함께 확률이 증가하고 당신에게 대한 비판적인 공격은 당신이 자연 완벽 효과를 줄이고 83d."
rows["191:356117469"]="공업급 폐기물 보관판 또는 현지인들이 부르는 것처럼, 기둥 쓰레기 덮개 \010\010파이프 잔재와 의심스러운 기술로 강화된 공격이나 판단을 막는 데 완벽합니다"
rows["191:664786410"]="이 토큰은 글로벌 프로그레시션 6 롤터 토큰입니다. 이것은 스톰윈드 (쿼터마스터 하드윈), 오그리마 (Warbringer Krogash) 또는 부티 베이 (Zazzle Refitwick) 에서 발견된 판매자에서 교환 할 수 있습니다."
rows["191:859927040"]="보수꾼들은 이 유물을 스트롬가르드 안에서 사용하도록 당신에게 맡겼으니,"
rows["191:863283697"]="이 친구를 불러내는 법을 가르쳐줍니다. \010\010 이건 전투가 아닌 동반자입니다.\010 \010그들은 작은 모자를 착용하는 것을 좋아합니다. 하루 동안 너무 많이 입지 않습니다. 모든 모습을 제대로 다듬는 시간을 줘야 합니다."
rows["191:904612245"]="오른쪽 클릭!\010\010클래스를 선택하고 수신:\010- 달빛의 불완전한 정의의 부담\010- 워디언의 달빛 워크블레이드\010- 타이드 젠더\010- 스타 피어서\010- 아샤다르, 암흑의 예언자\010- 웨일라이트 디펜더"
rows["191:934276607"]="이 토큰은 글로벌 프로그레시션 5 롤터 토큰입니다. 이것은 스톰윈드 (쿼터마스터 하드윈), 오그리마 (Warbringer Krogash) 또는 부티 베이 (Zazzle Refitwick) 에서 발견된 판매자에서 교환 할 수 있습니다."
rows["191:954516822"]="불성스러운 분노를 죽음의 기사에게 주며 공격 속도를 % 증가시키고, 이동 속도를 1% 증가시키고 모든 능력에 대한 글로벌 냉각을"
rows["192:1299915136"]="악성 에너지로 흐르는 덩어리, 검은 피의 병. 마너로스의 저주받은 생명은 오크들을 감염시키고 불타는 군단의 의지와 묶었다. 이 샘플은 여전히 강력하고 휘발성적이다."
rows["192:1457659594"]="당신의 힘 단어: 방패가 완전히 흡수되거나 분해되면 당신은 즉시 2전체의 % 마나, 그리고 당신은 완전히 보호된 목표에 에너지를 공급할 기회를 가지고 있습니다 마나,"
rows["192:1818619994"]="이 산이 날 수 있는 방법을 가르쳐줍니다\010\010스톰하임 산맥에서 태어난 이 끔찍한 폭풍과 규모의 융합은 맹수를 쫓아 하늘을 불태워버립니다."
rows["192:2103413689"]="무장 피해를 처리하는 불성스러운 공격은 물리 피해 부가로 추가됩니다. 또한, 목표에 있는 각 질병에 대해, 당신은 물리 피해에서 추가적으로 암흑 피해으로 처리합니다."
rows["193:1013687381"]="일단 보호되면, 대상이 다시 신성한 방패, 신성한 보호 또는 보호 손으로 공격할 수 없습니다 복수 분노를 사용할 수 없습니다."
rows["193:191852396"]="얼음 함정이 설치되어 첫 번째 적을 동원하여 모든 행동을 방지합니다."
rows["194:1106808182"]="우호적인 단체를 유도하여 공격의 격렬한 격렬을 일으킨다. 이는 그들의 물리 피해를 %로 증가시키지만, 그들은 초마다 최대 건강과 동등한 건강을 잃게 됩니다."
rows["194:1459380203"]="이 산이 날 수 있는 방법을 가르쳐줍니다\010\010하이마운틴의 언덕에 사는 가장 사랑스러운 종 중 하나인 이 동물은 얼어붙는 눈 폭풍 속에서 몇 달 동안 살아남을 수 있습니다."
rows["194:1922747958"]="당신의 건강이 20% 건강 상태 또는 그 이하의 상태에서 Drain Life에 의해 배출되는 양을 증가시키고, 당신의 목표가 35% 건강 상태 혹은 그 아래의 상태에서 그림자 주문으로 인한 피해를 증가시킵니다."
rows["194:418957460"]="죽음의 파업이나 오블리테이트를 때릴 때마다 얼음과 불성스러운 루너가 활성화되면 죽음의 루너가 될 가능성이 있습니다."
rows["194:490956718"]="당신의 Voidwalker의 고문, 그림자 소비, 희생 및 고통 주문의 효과를 % 증가시키고, 당신의 Felguard의 악마 광기 효과에 대한 전투력 보너스를 증가시킵니다."
rows["194:511217069"]="당신의 힘 단어: 방패가 완전히 흡수되거나 분해되면 당신은 즉시 2.5전체의 % 마나, 그리고 당신은 완전히 보호된 목표에 에너지를 공급할 기회를 가지고 있습니다 마나,"
rows["194:550740891"]="오른쪽 클릭!\010\010클래스를 선택하고 수신:\010- 부활한 악몽의 끔찍한 옷\010- 끔찍한 악몽의 쌍둥이 스카이트\010- 끔찍한 악몽의  ⁇ 한 병\010- 부활한 악몽 스티드의 리인"
