rows["195:1038445691"]="@미딕 레이드@ 보너스 마크, 오브, 루너 및 레이더 칭찬 또는 개인 약물을 포함할 수있는 기회를 가지고 있습니다.\010\010개인 로트는 당신이 선호하는 기기 유형에 대한 습격에서 기기를 선택할 수 있습니다."
rows["195:436178324"]="희귀하고 수입된 것인데 신비한 것에 빠져있었을지도 모릅니다. 판다렌 예술가들이 한 번 이 그림으로 일몰을 칠해서 먹었다고 합니다. \010\010그림, 찌르는 일 또는 낯선 사람을 인상시키는 일"
rows["195:586511122"]="임박한 멸망으로 목표물을 저주하여  암흑 피해 만약 목표물이 이 손상을 당했을 때 경험이나 명예를 얻으면, 유해보호가 소환될 것입니다."
rows["196:1212556"]="즉시 타겟을 불로 태워서, 즉각적으로 화염 피해 및 화염 피해를 일으킨다. 이 주기적인 손상은 비판적으로 공격할 수 있으며 캐스터의 주문 속도에 따라 더 빠르게 발생하게 될 것입니다."
rows["196:163948719"]="캐스터를 보호하고, 장갑을 증가시켜 1, 그리고 마법과 효과로 생성된 건강의 양을 증가시키는 장갑 마법의 한 종류만 언제든 마법을 활성화시킬 수 있습니다."
rows["196:1640326440"]="고통의 저주, 부패와 부패의 씨앗의 피해를 증가시키고 당신의 유용한 괴로움 주문과 시간적 피해 효과를 추가로 제거 할 가능성을 감소시킵니다."
rows["196:29109110"]="이 산이 날 수 있는 방법을 가르쳐줍니다\010\010이 산은 스톰윈드의 석조가 깎아 지었으며, 이 돌의 그리폰은 얼라이언스의 끈질긴 용기를 상징합니다."
rows["196:568685554"]="주요 도시에서 레리쿼리 무기 판매자 티라크시스를 찾아서 이 토큰을 보상으로 교환해 주세요\010\010바자르 토큰은 오일로 경매소에서 또는 DP로 웹샵에서 얻습니다."
rows["197:1200673268"]="곰 형태 또는 디렉터 베어 형태에서 극대화를 다루는 때마다, 당신은 야생 방어를 얻으며 전투력의 다음 물리적인 공격으로 인해 입은 피해를 줄입니다."
rows["197:1223497568"]="당신의 Faerie Fire 주문은 또한 목표가 매술 공격에 의해 타격을 받을 확률을 %로 증가시키고 극대화 페어 화재로 인한 피해를 보는 확률이 높습니다."
rows["197:178864861"]="만약 와이번 스팅이 제거되면, 디스플러는 남은 기간 동안 와이번 스틴에 의해 영향을 받으며,"
rows["197:2109693954"]="가려동과 포장물의 속도 보너스를 %로 증가시키고, 가려동이 장착되는 동안의 속도를 증가시킵니다."
rows["198:1127034628"]="체인 라이트닝 매기의 냉각을 .75 초로 줄여, 지구 결합 토템은 또한 발사 시 목표물을 뿌리 내리는 기회를 가지고 있습니다. 그리고 플라임 쇼크에 의한 주기적인 피해는 증가합니다."
rows["198:1736734025"]="체인 라이트닝 매기의 냉각을 2.5 초로 줄이면 지구 결합 토템은 또한 발사 시 목표물을 뿌리내릴 기회를 갖게 되고"
rows["198:1876831630"]="Kezan Blasterboots Inc. 는 이 제품을 사용함으로써 발생할 수 있는 다리 결실, 변형 화상, 불면증, 마른 입, 자극성 또는 갑작스러운 incontinence 발병에 대해 책임을 지지 않습니다."
rows["198:389865471"]="섬 아래에서 악의 침착에 의해 오염된 토양의 샘플. Yth ⁇ qwa ⁇ s 부패는 천천히 표면에 침투, 악성 속삭임. 잠은 괴물들이 만든 소란 가운데 피할 수 없습니다."
rows["198:553428623"]="그림자를 통과하고 적 뒤에 다시 나타나고 움직임을 증가시키는 시도에 대한 다음 능력의 손상은 증가하고, 발생 위협은 감소 Lasts 63d."
rows["198:616322157"]="플라메스트라이크로도 알려진 페로멜론은 고대 고성기 룬 블레이드입니다. 옛날의 전쟁 이전에도 다트레마르 선스트라이더가 사용했습니다."
rows["198:939485282"]="체인 라이트닝 매기의 냉각을 1.5 초로 줄이면 지구 결합 토템은 또한 발사 시 목표물을 뿌리내릴 기회를 갖게 되고"
rows["199:1292582401"]="@세계벼림이 유적은 발랜드의 암석으로 형성되어 있으며, 지구의 숨겨진 힘과 함께 웅장합니다. 그것을 운용하는 사람들은 그 땅 자체가 충격과 지진에 반응하고, 모든 타격에 반향을 일으키고 있음을 느낄 수 있습니다."
rows["199:1466010540"]="목표물의 움직임을 줄이고, 던진 무기 피해를 증가시키는 마무리 동작:\010   1 점: - 손해\010   2 점: - 손해\010   3 점: - 손해\010   4 점: - 손해\010   5 점: - 손해"
rows["199:1516648507"]="이 같은 막대기, 어두운 별의 모양으로 조각된, 여왕 사이벨의 가장 충성스러운 종들에게 주어졌습니다."
rows["199:1531789016"]="마법을 배제하는 15 야드 반경에서 모든 유해 마술을 제거하는 5 친선적 목표 및 1 이로운 마법을 5 적의 목표물, 보통은 미끄러지지 않는 마법을 제거할 만큼 강력합니다."
rows["199:1578167936"]="개인 대기 재구성기를 사용하는 방법을 가르쳐줍니다. 고블린이 설계한 가상 현실 장치입니다. 그것은 하늘의 인식을 변화시킵니다. 대륙과 전투장에서만 사용할 수 있습니다."
rows["199:1897425993"]="냉기 피해까지 목표물을 추워내고 얼음열병으로 감염시키는데, 이것은 주기적으로 손상을 입히고 얼음 현존할 때 매우 높은 위협을 위해 수습 및 랜딩 공격 속도를 줄이는 질병입니다."
rows["199:2015898714"]="당신이 건강 상태 또는 그 이하의 목표물을 불태우고, 불태우거나 불태우는 경우, 당신의 영혼 불 주문의 casting 시간은"
rows["199:519628098"]=" ⁇  모로흐에서 미르신스의 형제로부터 되찾은 이 토테마는 그 시대에 많은 소모를 보았지만, 이후 그녀가 그것을 넣은 매력은 인근의 지옥을 끄는 능력이 있습니다."
rows["199:703837179"]=" ⁇ 은 미술을 수행, 손상되지 않지만 큰 양의 위협을 감소, 적의 공격 가능성이 덜합니다. 또한,"
rows["199:871393125"]="타겟의 갑옷을 분해하여 Sunder Armor 효과를 일으킨다. 또한, 무기 손상을 유발하고 목표에 Sunder Armor를 적용하는 경우에도 Sunder Armor 효과는 여러 번 쌓일 수 있습니다."
