rows["200:1175834490"]="신펠이 심장을 찢어지고 불멸이 되자 그의 피는 힘의 궤도로 숨어 있었습니다.\010심장이 그것을 지지하지 않으면 그 혈액은 서서히 부패하기 시작했지만, 그 안에 있는 힘은 남아 있습니다."
rows["200:1674065426"]="번개 방패 궤도에서 발생한 피해를 % 증가시키고, 물 방패 궤도로부터 얻은 마나의 양을 증가시키고, 지구 방패 궤도들에 의해 이루어지는 치유의 양을 증가시킵니다."
rows["200:1712557739"]="트랜스모그리피케이션으로 외모를 향상시키기 위해 만들어진 화장품 마술입니다. 데이터베이스에서 그것을 찾아보고 어떻게 보이는지 확인하십시오. 다른 플레이어, 경매소 또는 잃어버린 가게에서 얻을 수 있습니다."
rows["201:1140467195"]="모든 속성을 %로 증가시키고, 미사 공격에 의해 심각한 타격을 받을 확률을 %로 감소시키고, 그리고 Bear Form에서 옷과 가죽 아이템의 갑옷 기여를 증가시킵니다."
rows["201:1423801096"]="건강 함선 매술로 전달되는 건강의 양을 증가시키고 건강 비용을 감소시킵니다. 또한, 당신의 소환된 악마는 건강 함선의 영향으로 있으면 더 적은 피해를 입습니다."
rows["201:1450944440"]="핫스워프 프레임\010\010Atiesh, Greatstaff의 수호자를 변경하는 구성 요소로 사용된다. 직원의 복원된 버전이 필요합니다. 이것은 항목을 만드는 데 구성 요소로 간주되지 않습니다."
rows["201:1672186748"]="룬 무기를 룬으로 부착하여 다음의 손상을 증가시킬 수 있습니다 2 프로스트 또는 암흑 피해룬 무기를 수정하려면 에본 홀드에서 룬 포지션이 필요합니다."
rows["201:1709296487"]="이 산을 불러내는 법을 가르쳐줍니다.\010\010이 마운트는 PvP 프로게이션 (반닐라) 가 종료될 때 1v1 또는 10 2v2 순위표의 상단에 10 위치함으로써 얻는다."
rows["201:1880128635"]="이 마나 자유의 손, 희생의 손, 구원의 손의 비용 %로, 구원의 손과 희생의 손의 효과를 더 높여줍니다."
rows["201:1993162381"]="입장을 바꾸면 분노의 점들을 더 많이 유지하게 되고, 방어적인 자세를 할 때 피 갈증과 치명적 공격 능력으로 인한 위협도 크게 증가합니다."
rows["201:832437655"]="이 제품들은 Transmogrification와 함께 사용될 예정입니다. 이 제품들은 다른 플레이어, 경매소 또는 잃어버린 가게에서 구입할 수 있습니다."
rows["202:1028311415"]="여러분 그룹 에 있는 사람 들 이 손상 이나 치유 의 마법 을 받으면, 현재 목표 를  ⁇  수 있는 기회 가 있습니다. 이 효과 는 초당 한 번 이상 발생 할 수 없습니다."
rows["202:1275714888"]="친선적인 플레이어는 라이트웰을 클릭하여 30전체 건강의 %는 효과를 취소합니다. 10 혐의"
rows["202:431593913"]="광대왕의 동료인 포스포렌스  ⁇ 은 그의 추종자들 가운데 첫 번째였으며, 그들은 오직 Sicklight의 자녀들이 숭배하는 방사능의 무서운 신과 길을 갈라진 유일한 사람들이었다."
rows["202:78899709"]="적의 목표를 찢어내고, 피해를 입히고 출혈 피해가 증가하여 전투력이 효과는 같은 목표에 여러 번 쌓여 있습니다."
rows["202:937345702"]="극대화의 기회를 높이고, Obliterate를 캐스팅하고 Obliterate는 Howling Blast에 냉각을 재설정할 수 있고 다음 Howling Blast이 룬을 사용하지 않도록 할 수 있습니다."
rows["202:937712363"]="뱀 스팅과 와이번 스팅의 피해를 증가시키고 마나 또한, 당신의 지팡이 손상 시간이 지나면서 효과에 의해 해소될 확률을 감소시킵니다."
rows["203:1071988287"]="2 불공전, 불공전, 화소, 살아있는 폭탄 또는 얼음불 발트를 사용하여 연속적으로 비 주기적인 주문을  ⁇  때마다 다음 피로블라스트 마법의 투 cast이 즉시 투 cast 될 가능성이 있습니다."
rows["203:1680987900"]="이 산이 날 수 있는 방법을 가르쳐줍니다\010\010이 산은 오그리마의 돌 작업자들이 깎아 지었고, 이 돌풍 승마자는 호드의 흔들리지 않는 힘의 상징입니다."
rows["203:1997949717"]="경험이나 명예를 주는 상대방을 죽인 후, 극대화 다음 악성 공격, 출혈,  ⁇ 돌, 부자, 함정 또는 유령 공격에 대한 기회입니다. 43d."
rows["203:1998052683"]="경험이나 명예를 주는 상대방을 죽인 후, 극대화 다음 악성 공격, 출혈,  ⁇ 돌, 부자, 함정 또는 유령 공격에 대한 기회입니다. 49d."
rows["203:713123254"]="<눈의 맹면은 불확실한 미래를 비전하고 있습니다. 악마의 그림자, 낯선 하늘, 얼어붙은 황무지... 그리고 불."
rows["204:1175086313"]="이 친구를 불러내는 법을 가르쳐줍니다.\010\010상승의 책에서는 모든 능력을 훈련시킬 수 있습니다\010\010경매소에서 또는 DP에서 얻을 수 있습니다.\010\010이건 전투가 아닌 동반자입니다."
rows["204:132050418"]="이 가방에는 로드 스타터 다이스가 포함되어 있습니다. 이것은 당신이 레벨 1에서 개별 레벨 1 능력을 다시 볼 수 있도록 할 것입니다. 그리고 당신의 헛소리 컬렉션을 통해이 영역의 모든 캐릭터에 사용할 수 있습니다."
rows["204:2031032724"]="죽은 스프리트에서 추출된 비는  ⁇ 이 흐르고 시체가 사라질 때까지 흔들리면 마법의  ⁇ 이 그로부터 빠져나갑니다."
rows["204:717265294"]="스와이드, 즉 소스를 통해 그늘숲아직도 공포와 먼지 냄새가 나고 있어요 \010\010기분 조명이나 바람직한 정신을 멀리하는 데 좋은데, 위험이 가까이 있을 때만 조명을 켜고 있다고 합니다."
rows["205:1035880772"]="당신의 죽음의 코일의 희생자들이 불성스러운 곤충들의 잔혹한 무기로 둘러싸여있도록 해줍니다. 그리고 죽음 코일의 피해를 덜어주고,"
rows["205:1079093999"]="@카라잔 크립트 신화@ 엘우네가 숨길 수 있는 것처럼 빛 태양의 빛은 어둠의 별이 꿈에 의해 은폐되었다는 것과 같습니다.\010하지만 가장 긴 행식은 우주 역사의 짧은 순간일 뿐이죠"
rows["205:1198303229"]="무기 피해를 주는 즉각적인 공격 (다검이 장착되어 있다면) 그리고 목표물을 출혈시키는 공격으로, 목표물에 처리된 모든 물리 피해을 최대 라스트 충전 또는 어워즈 1 컴보 포인트까지 증가시킵니다."
rows["205:1231558791"]="모든 당원 및 파격 멤버들에게 메리, 랜지, 마법을 던지는 속도를 높입니다. 이 효과가 완료되면 영향을 받은 사람들은 Sated이 될 것이며 24d 동안 다시 Bloodlust에서 혜택을 누릴 수 없습니다."
rows["205:2127876866"]="무기를 룬으로 부착하여 2%의 추가 무기 피해를 발생시키고 냉기 피해로 적들의 Frost 공격에 대한 취약성을 높입니다. 룬 무기를 수정하려면 Ebon Hold에서 룬 포지 (Rune Forge) 를 필요로 합니다."
rows["205:446546189"]="엔드게임 마나스타머스에서 얻은 |cffFFFFFF수준 196 레벨 226.|r\010\010|cFFffffff내용:|r \010\010+ 정상적인 카라잔 기어\010\010|cFFffffff 포함 가능성은:|r\010\010+ 영웅적인 카라잔 기어\010+ 영웅적인 던전 기어"
rows["205:83879381"]="Power Word: Shield을 던지면 목표의 움직임 속도를 d로 증가시킬 수 있고, 폐지질환을 던지면 스스로도 깨끗하게 할 수 있는 기회가 있습니다. 1 질병 외에도 독효과가 있습니다."
rows["206:1473112750"]="@|cFFCC0000Bloodforged|r@Elune가 빛의 태양을 숨길 수 있는 것처럼, 어두운 별도 꿈에 의해 은폐되었습니다.\010하지만 가장 긴 행식은 우주 역사의 짧은 순간일 뿐이죠"
rows["206:1565654827"]="혼돈적인 미묘한 에너지는 고속 교통 포털에서 결정화됩니다. 선송 랜치의 토양은 이 에너지를 안정시켜 농장에서 깨질 수 있는 조각을 만들어 큰 도시로 가는 단점 포털을 열게 됩니다."
rows["206:1677396469"]="나마리안 성원의 고령들이 '친구'라고 생각하는 사람들에게 선물한 마법의 메달리온."
rows["206:188391635"]="당신의 화노의 마법으로 인해 발생한 피해를 %로 증가시키고 극대화 당신의 별불 마법이 달불 주문에 의해 영향을 받은 목표물에 지나갈 확률입니다."
rows["206:222661036"]="이 산이 날 수 있는 방법을 가르쳐줍니다\010\010이  ⁇ 은 PvP 진행 (TBC) 이 종료될 때 1v1 또는 10 2v2 순위표의 상단에 10 위치함으로써 얻는다."
rows["206:447100081"]="코스메틱 무기는 트랜스모그리피케이션으로 사용될 예정입니다. 카스메틱 무기가 어떻게 생겼는지 볼 수 있습니다. 이 만티 컬렉션에서 다른 플레이어, 경매소, 또는 잃어버린 가게에서 얻을 수 있습니다."
rows["207:233277857"]="이 이상한 동전은 밀하우스 의 미니크적 미소 로 장식 되어 있다. 마나폭풍 에서 레벨 을 처음 완수 한 사람 에게 수여 됩니다. 당신은 당신의 수도 도심 에 있는 밀하우스 마나폭풍 에서 훌륭한 아이템 으로 교환 할 수 있습니다!"
rows["207:31977612"]="명성 동안 또는 새로운 캐릭터에서 레벨 1에서 사용할 수있는 무작위 스킬 카드입니다.\010\010스킬 카드는 특정 마법을 작성할 수 있도록 보장합니다.\010\010스킬카드는 수도의 시라스 다크문에서 얻습니다."
rows["207:391790693"]="@카라잔 크립트 - 미딕@ 엘루네가 숨길 수 있는 것처럼 빛 태양의 빛은 어둠의 별이 꿈에 의해 은폐되었다는 것과 같습니다.\010하지만 가장 긴 행식은 우주 역사의 짧은 순간일 뿐이죠"
rows["207:594347755"]="모든 당원 및 파격 멤버들에게 메리, 랜지, 마법을 던지는 속도를 높인다. 이 효과가 완료되면 영향을 받은 사람들은 고갈되고 23d 동안 다시 영웅으로부터 이익을 얻을 수 없습니다."
rows["207:676852789"]="이 마법은 바로 발사되는 순간, 다음 번개 발작, 체인 번개 또는 라바 폭발 주문이 됩니다. 또한 Elemental Mastery는 자연의 Swiftness과 함께 냉각을 공유하기 위해 속임수를 더 빨리 얻습니다."
rows["208:1008769934"]="매 매티크+ 완공에 대해 50 미틱 동전을 수여받습니다. 일주일에 1550 동전을 청구할 수 있습니다.\010\010이 제한은 모든 히어로즈 주간으로 1550 동전으로 증가합니다.\010\010신화 동전은 신화 캐시와 별도로 계산됩니다."
rows["208:1052684596"]="이 기호는 당신의 통제하에 있는 애완 동물로 간주됩니다. 일반적인 죽음의 기사 괴리와 달리, 당신의 애완 동물은 제한된 기간이 없습니다."
rows["208:1940473973"]="이 글래스 는 기록물 판매자 들 이 판매 하고, 작가가 제작 하는 필수적 인 반응물 이다. 마법 책 에서 글래스를 지우고 다시 적용 하기 위해 필요 합니다. 이 특정 파우더는 80 수준 이나 그 보다 낮은 수준 에만 사용 될 수 있습니다."
rows["208:363444675"]="코스메틱 무기의 세트 (Cosmetic Weapon Set) 는 트랜스모그리피케이션으로 사용되도록 되어 있습니다. 당신은 바니티 컬렉션에서 코스메틱 세트를 볼 수 있습니다. 이 제품은 다른 플레이어, 경매소 또는 잃어버린 가게에서 얻을 수 있습니다."
rows["208:529641816"]="진노로 목표물을 저주하여, 암흑 피해에 대한 원인이 됩니다 이 손상은 처음에는 천천히 처리되며, 저주가 전체 기간을 달성함에 따라 쌓이게됩니다. 마법사당 한 번만 단 하나의 목표물에 활동할 수 있습니다."
rows["208:573342082"]="당신의 동굴 열은 에본 전염병으로 변해 9질병에 의한 피해를 증가시키는 것 외에도 극대화 무기와 마법이 항상 찾아오는 기회입니다."
rows["209:142392646"]="언제부터인지  ⁇ 기기를 계속 매료시키는 법을 가르쳐줍니다 지능 마법을 통해 해를 치유하거나 처리하는 데에도 도움이 됩니다 마나 낮은 수준입니다. 372 또는 더 높은 항목"
