rows["209:2003210637"]="@세계벼림카인 가족 동굴 옆에 발견된 상자처럼, 코볼드들에 의해 약탈당해 있습니다. 이 땅에는 그들의 존재가 드물습니다. 왜냐하면 그들은 토양 아래에서 무엇을 살고 있는지 알고 있기 때문입니다."
rows["209:2133852728"]="적을 개구리로 변환합니다. 마법을 사용하면서 표적이 공격하거나 마법을 할 수 없습니다. 발생한 손상은 효과를 방해할 수 있습니다. 한 번에 하나의 표적을만 마법을 사용할 수 있습니다. 인간과 짐승에만 작동합니다."
rows["209:391385113"]="당신의 동굴 열은 에본 전염병으로 변해 13질병에 의한 피해를 증가시키는 것 외에도 극대화 무기와 마법이 항상 찾아오는 기회입니다."
