rows["210:1150523502"]="토테엄을 소환하여, 인근의 당원에게 던진 유해한 주문을 스스로로 다시 방향을 전환시켜서 토테임을 파괴합니다."
rows["210:2023245322"]="당신의 스테이디 슈트 샷은 다음 목표, 아카네 슈트 또는 치메라 슈트가 만든 피해를 %로 증가시킬 수 있고, 다음 목표, 아칸 Shot 또는 치메라 쇼트의 마나 비용을 20s2%로 줄일 수 있습니다."
rows["210:2067027285"]="위험성이 높은 경우 사망에 빠지지 않습니다.\010\010고 위험 네더스톰에서 발견된 빈  ⁇  은 캐시를 열면 'No-Retreat' 디버프를 유발하여 탈출 매력이 안전으로 데려다 줄 수 있습니다."
rows["210:314803534"]=" ⁇ 은 목표물을  ⁇ 고, 마나을  ⁇  (캐스터의 최대 최대 마나까지) 를  ⁇ 고,  ⁇ 은 수량 300%에 해당하는 에너지를  ⁇ 어. 한 사냥꾼당 단 한 개의 스팅만이 하나의 목표물에 능동할 수 있습니다."
rows["211:1100444239"]="공격 대상에게 손상을 입히면 그 효과를 취소할 수 있습니다. 공격 대상에서 깨어나면, 공격 공격은 자연 피해에 의해 발생합니다."
rows["211:1967284818"]="목표 지역에서 폭력적인 폭풍을 일으키며 매초마다 자연 피해의 적을 일으켜, %로 이동 속도를 줄이고, ][ ] 그리고 라스트 드루이드가 주문을 유지하기 위해 채널을 통해 공격하는 시간 사이의 시간을 늘린다."
rows["211:2079054922"]="번개 발사, 체인 번개, 파이어노바, 라바 폭발 주문의 범위를 마일로 증가시키고, 천둥 폭풍 주문의 반경을 %로 증가시키고,"
rows["211:211502119"]="보호할 수 있는 친선적 목표의 영혼을 끌어들여 피해를 흡수합니다. 8d."
rows["211:639876483"]="희귀 한 꽃 이 있는데, 그 꽃 피는 줄기 를 둘러싼 잎자루 를 깎아 내며 슬픔 을 느끼게 한다. 한때 데드윈트 패스 에 살았던 어린 아이 는 그 꽃 을 행복하게 하고 싶었지만, 이 보존 된 꽃 은 더욱 슬픈 것 처럼 보인다."
rows["212:1147021716"]="미스터스 (Stealthed) 로까지 목표물을 무능하게 합니다. 전투에 있지 않은 인간, 짐승, 악마 및 용마자에만 작동합니다. 발생한 모든 손상은 목표를 다시 살려줍니다. 한 번에 1 목표만 훼손 할 수 있습니다."
rows["212:1866842893"]="위험성이 높은 경우 사망에 빠지지 않습니다.\010\010위험성 높은 네더스톰에서 발견된 야생동물들의 둥지를 허물게 하는 유령들을 유혹합니다."
rows["212:652664650"]="시간이 지남에 따라 손상을 일으키는 완성 동작. 전투력:\010   1 점: 손상    2 점: 손해    3 점: 손해    4 점: 손해    5 점: 손해"
rows["213:1138111861"]="아자르 페어 프로모션 티켓이 있습니다. 이 티켓을 페어 게이트에 제시하세요. 늦지 마세요! \010\010당신 의 가장 광대 한 꿈 에서도 당신 을 기다리고 있는 놀라운 놀라움 을 상상 할 수 없습니다!"
rows["213:1140056704"]="원인  화염 피해 때리는 경우, 당신의 극대화 당신의 정신에 의해 평가되고, 당신은 비중적으로 공격 될 확률을 감소합니다 한 종류의 갑옷 마술은 언제든지 마지에 활동할 수 있습니다. 45d."
rows["213:1140073865"]="원인  화염 피해 때리는 경우, 당신의 극대화 당신의 정신에 의해 평가되고, 당신은 비중적으로 공격 될 확률을 감소합니다 한 종류의 갑옷 마술은 언제든지 마지에 활동할 수 있습니다. 46d."
