rows["213:1372518314"]="@|cFFCC0000영웅적 인 피가 만들어졌어요|r@엘루네가 숨길 수 있는 것처럼 빛 태양의 빛은 어둠의 별이 꿈에 의해 은폐되었다는 것과 같습니다.\010하지만 가장 긴 행식은 우주 역사의 짧은 순간일 뿐이죠"
rows["213:1448542436"]="I 및 II 전문의의 전환을 할 수있는 기회를 해제하고 추가 미스틱 매혹적인 전문성을 해제합니다.\010\010경매소, 명예, 시장 토큰 또는 가게에서 사용할 수 있습니다."
rows["213:1520016241"]="비 주기적인 착륙 후 극대화 불과 얼음, 또는 자연 피해 마법을 입력하면 클리어캐스팅 상태가 됩니다. 마나 다음 손해나 치유의 비용 46s1%."
rows["213:421411731"]="플래시 치유, 치유, 더 큰 치유, 결합 치료, 회개, 메딩 기도, 치유의 기도 또는 치유의 원경 주문에서 중요한 효과를 얻은 후 당신의 목표의 물리 피해를 감소시킵니다."
rows["213:526642107"]="한동안, 오닉시아은 스톰윈드에서 최고 공무원 중 한 명으로 위장되었다. 결국 그녀는 바리안 윈, 브롤 베어만틀, 발레라 산길아르, 그리고 타르가스 앤빌마르의 도움으로 윈저 상사에게 위장 공개되었다."
rows["213:629159168"]="@세계벼림@ 인류가 처음 발걸음보다 훨씬 전에 살았고 사라진 트롤의 허리뼈를 사용했습니다. 수호자의 신전을  ⁇ 은 사람들은 그러한 명예의 끔찍한 비용을 알고 그렇게했습니다: 영원한 노예제도."
rows["213:939538060"]="타겟과 같은 클래스를 공유하는 모든 공격 또는 그룹 구성원에게 더 큰 킹스 축복을 제공합니다. 플레이어의 전체 통계를 증가시키는 것은 플레이어가 한 번에 팔라딘당 하나의 축복이있을 수 있습니다."
rows["214:1078004133"]="@세계벼림@Eldara에 새겨진 마크리 는 도시를 공격자로부터 방어하기 위해 이 같은 무기에 달려간다. 그것을 움직이는 매력은 오래전부터 사라졌지만, 그것은 현대 크로스보와 비슷한 기능을 하고 있습니다."
rows["214:1620167367"]="만약 경험이나 명예를 주는 인형의 시체가 없다면, 마법을 완성하기 위해 시체 먼지를 공급해야 합니다. 한 번에 최대 한 명의 Ghoul를 가질 수 있습니다. 85d."
rows["214:2029031471"]="공격이나 집단의 모든 구성원에게 대상을 공유하는 큰 축복 전투력 플레이어는 한 번에 팔라딘당 하나의 축복만 받을 수 있습니다."
rows["214:297244086"]="테론 고레피엔드는 달라란의 안전한 유물에서 눈을 빼내어 금 동전을 에벤티드의 분수 속으로 던졌는데, 이는 그가 원하는 것이 아니라 그가 가져가서 도망친 것에 대한 '결제'로 했다고 주장한다."
rows["215:134353301"]="코스메틱 무기 세트 (Cosmetic Weapon Set) 는 트랜스모그리피케이션으로 사용되도록 되어 있습니다."
rows["215:1464054457"]="무장이 증가한다 적이 투자를 공격하면, 그들의 움직임이 느려질 수 있고 공격 사이의 시간이 증가할 수 있습니다."
rows["215:522428109"]="발에 건강이 있는 무동적인 센트리 토템을 불러서 근처의 지역을 볼 수 있게 해 주며 공격하는 적들을 경고합니다."
rows["215:591201479"]="밀하우스 마나폭풍의 깨진 프로토타입 조각은 마나폭풍에서 길을 열어주었습니다. 밀하우스는 그가 보내는 것을 마나폭풍로 쉽게 끌어낼 수 있지만, 아마도 그러한 장치에 대한 다른 필요성을 찾을 것입니다."
rows["216:1262275327"]="매술의 중요한 효과를 %로 증가시키고, 중요한 타격을 받은 후 집중된 의사 효과를 얻을 수 있습니다. 37d."
rows["216:1264420452"]="매술의 중요한 효과를 %로 증가시키고, 중요한 타격을 받은 후 집중된 의사 효과를 얻을 수 있습니다. 41d."
rows["216:1479419816"]="영혼들이 끝없는 행렬로 순항하는 마지막 지평선에서 찢어진 스펙트럼 조각. 고대 트롤들은 영세계의 예술가이자 공예가였으며, 이런 조각들은 그들의 가장 소중한 보물 중 하나였습니다."
rows["216:509596930"]="파티 또는 레이드 멤버에 손상을 옮기는 손상을 배치합니다. 캐스터가 최대 건강을 이전하기 전까지. 플레이어는 한 번에 팔라딘당 한 손만 가질 수 있습니다."
rows["216:692388819"]="이동 속도가 증가하는 형태로 모양을 변경하여 또한 폴리모프 효과로부터 캐스터를 보호합니다. 야외에서만 사용할 수 있습니다.\010\010형태를 바꾸는 행위는 폴리모프와 운동에 영향을 미치는 효과를 방출합니다."
rows["216:742532081"]="적이 접근할 때 폭발하는 불사고를 설치하여 화염 피해을 일으켜 모든 적들을 추가적으로 화염 피해로 불태워 야드 내에 있는 모든 사람에게 붙여 놓습니다. 함정이 존재할 것입니다 한 번에 하나의 함정이만 활동할 수 있습니다."
rows["217:1331367254"]="독을 당한 목표물에 대한 모든 공격의 위험성 %를 증가시키고, 당신에게 적용된 모든 독효과를 %로 줄이고, Envenom에게 치명적인 독을 섭취하지 않는 기회를 제공합니다."
rows["217:1689987132"]="당신의 Fade 능력은 이제 Shadowform에서 사용될 때 모든 움직임에 영향을 미치는 효과를 제거할 수 있고, Shadowform에서 어떤 Shadow spell을 casting 할 때 손실되는 casting 또는 channeling 시간을 줄일 수 있습니다."
rows["218:102478636"]="당신의 부패와 배수 생활은 상대방에게 피해를 입은 후 당신이 그림자 트랜스 상태에 들어갈 수있는 4%의 기회를 제공합니다. 그림자 트랜스는 다음 그림자 볼트 주문의 캐스팅 시간을 41s1%로 줄입니다."
rows["218:1029233879"]="당신의 부패와 배수 생활은 상대방에게 피해를 입은 후 당신이 그림자 트랜스 상태에 들어갈 수있는 2%의 기회를 제공합니다. 그림자 트랜스는 다음 그림자 볼트 주문의 캐스팅 시간을 41s1%로 줄입니다."
rows["218:1183402848"]="한 식물의 산성 침으로 인해 부분적으로 고해된 뼈. 괴물들의 과실로 태어난 혐오스러운 괴물의 척추 없는 턱에 그 끝을 맞기 위해 파에에서 즐거움을 추구하는 사람에게는 슬픈 끝입니다."
rows["218:1749806704"]="증가 극대화 당신의 마인드 블라스트, 마인드 플레이 및 마인드 세어 매기의 확률은 %로 증가하고 극대화 뱀파이어 터치, 독성 전염병과 그림자 단어의 기회"
rows["218:2032441903"]="< 글씨 한 편의 간편자 조각. 몇 마디는 읽을 수 있고, 그 밖엔 거의 없다. >\010\010불꽃이 그림자 앞에 무릎을 꿇는 때가 있었습니다."
rows["218:691319069"]="당신 의 대우수선 을 불러 주십시오. 그 의 경호적 인 시선이 당신 의 길을 알려 주도록 하십시오. 새벽 처럼 빛나는 깃털 으로 장식 된 이 충성 스러운 동반자 는 당신 의 모험 을 조용히 관찰 하고, 충성 과 힘 의 정신 을 상징 합니다."
rows["219:1564445761"]="공격이나 집단의 모든 구성원에게 목표와 같은 클래스를 공유하는 큰 지혜의 축복을 제공합니다.  마나 모든 5 플레이어는 한 번에 팔라딘당 하나의 축복만 받을 수 있습니다."
rows["219:899749940"]="@|cFFCC0000 시즌 리얼즈 일컬리티브|r@이 항목은 당신의 시즌 성과 컬렉션을 잠금 해제합니다. 이 항목은 당신이 시즌 동안 시즌 포인트를 얻을 수 있습니다. 이러한 포인트는 독점 화장품을 잠금 할 수있는 사용할 수 있습니다!"
