rows["220:2018034768"]="물리 피해을 증가시키는 마무리 동작은 Cat Form에서 사용할 때만 수행됩니다.\010   1 점: 14 초\010   2 점: 19 초\010   3 점: 24 초\010   4 점: 29 초\010   5 점: 34 초"
rows["221:1808409990"]="포세이큰 은 불일치자들의 전쟁 노력을 강화하기 위해 어둠의 여인이 오그리마의 깊숙한 곳으로 보낸 코보에서 물품을 훔쳤다."
rows["221:78517032"]="당신의 불구, 얼음불 발트 및 피로블라스트 주문의 손상을 증가시키는 금액이 당신의 주문력. 또한, 당신의 Ignite 재능이 손상으로 인해 모든 경우에, 당신은 당신의 기지를 회복 할 수있는 기회를 가지고 있습니다 마나."
rows["222:1392902433"]="목표 지역에서 폭력적인 폭풍을 일으키며 매초마다 적에게 자연 피해를 일으켜, %로 이동 속도를 줄이고, ][ ] 그리고 라스트 드루이드가 주문을 유지하기 위해 적들의 공격 사이의 시간을 늘리는 채널을 만들어냅니다."
rows["222:793736835"]="또한, 당신의 얼음 방과와 화재 방과에 의해 보호된 피해 주문을 부정하고 복원 할 수있는 기회를 제공합니다 마나 손해와 동등한"
rows["222:823489881"]="공룡은 정의의 정신으로 가득 차 있어 모든 전투 공격에 한 번만 할 수 있는 유일한 해 Seal이 공룡에서 활동할 수 있습니다.\010\010이 봉사의 에너지가 풀리면  신성 피해 적에게"
rows["222:844668420"]="당신의 그림자 롤트와 유령 주문은 그림자 포옹 효과를 적용하여, 당신이 대상에게 주기적으로 주는 그림자의 피해를 %로 증가시키고,"
rows["223:243392967"]="얼음 로 가득 찬 음악 상자, 상실과 후회와 야망의 멜로디 를 속삭이는 포세이큰이 것을 들고 있는 사람은 얼음 묶여 있는 여자의 눈물을 흘리는 울음을 거의 들을 수 있습니다. 그녀가 한때 있었던 마법사와 그녀의 운명을 상기시키는 것입니다."
rows["223:938143883"]="당신이 죽인 동물들이 파티와 동굴에서 일하지만, 습격에는 사용할 수 없습니다. \010\010이 동반자는 당신의 바니티 컬렉션에 추가되어 모든 캐릭터에 사용할 수 있습니다.\010\010이건 전투가 아닌 동반자입니다."
rows["224:1249939651"]="적의 표적을 추방하여 모든 행동을 막는 동시에 1개의 목표가 배척될 수 있습니다. 배영을 추방한 목표에 던지는 것은 주문을 취소합니다. 악마와 Elementals에만 작동합니다."
rows["224:1495879884"]="이 악기는 공격할 때, 투사에게 발생한 모든 피해는 당신의 임프, 보이드워커, 수쿠부스, 펠런 헌터, 펠가드 또는 노예 악마에 의해 발생한다. 그 피해는 막을 수 없다."
rows["224:1658408297"]="엔드게임 마나스타머스에서 얻은 |cffFFFFFF수준 376 레벨 406.|r\010\010|cFFffffff내용:|r \010\010+ 미틱 계층 4 기기\010\010|cFFffffff 포함 가능성은:|r \010\010+ 정상 뱀성굴 장비\010+ 미딕 던전 던전 기어"
rows["224:1758682237"]="위험성이 높은 경우 사망에 빠지지 않습니다.\010\010고위험 실리투스와 윈터프링에서 발견된 악마의 가짜 짐승들의 둥지를 열면, 피난 마법이 안전으로 데려다 줄 수 있습니다."
rows["224:2030912132"]="이 피꽃이 그 기간을 마친 후 또는 제거되면, 피꽃은 즉시 스스로 치유되고 Druid는 주문의 절반을 되찾습니다. 이 효과는 같은 목표에 여러 번 쌓일 수 있습니다."
rows["224:345092192"]="샤만에게 귀신늑대를 만들어서 5 귀신 늑대로서, 샤만은 운동 속도를 줄일 수 있는 효과에 의해 덜 방해를 받는다. 야외에서만 사용할 수 있다."
rows["224:451711594"]="죽음의 기사에게 맞서 싸우기 위해 군대의 괴물을 불러라. 괴물은 그 지역을 몰아치며, 할 수 있는 모든 것을 모욕하고 싸워요. 죽은 군대를 통한 동안, 죽음의 기사들은"
rows["224:694080121"]="당신은 번개를 불러내며, 당신을 에너지로 만들고, 주위에서 가까운 적들을 손상시킵니다. 당신에게 마나을 회복하고, 모든 근처의 적들에게 자연 피해을 제공하여 그들을 20 야드 뒤로 떨어뜨립니다. 이 마법은 놀란 동안 사용할 수 있습니다."
rows["225:1410758835"]="만약 당신이 연대 무기로 피해를 입히면, 다음 번개 발작, 체인 라이트닝, 작은 치유파, 치료파, 체인 치유 또는 스택에 의해 5 시간, 시간 17d."
rows["225:183137135"]="팔라딘을 d의 신성한 빛으로 채우며, 모든 전투 공격에 팔라딘을 치유할 기회를 주며, 오직 한 명의 봉호만이 팔라딘에서 언제든지 활동할 수 있습니다.\010\010이 봉사의 에너지가 풀리면  신성 피해 적에게"
rows["225:311076024"]="위험성이 높은 경우 사망에 빠지지 않습니다.\010\010고위험 실리투스와 윈터스프링에서 발견된 악마 묶여있는 숨겨진 캐시를 열면 안전으로 데려가는 탈출 마법을 방지하는 데 'No-Retreat' 디버프를 유발합니다."
rows["225:4617242"]="당신은 캐스터에서 30 야드 내에 있는 모든 목표물에 하늘에서 별의 파동을 불러 일으킨다. 또한 비전 피해 를 상대 대상으로부터 야드 내에 있는 다른 모든 적에게 비전 피해를 유발합니다. 최대 20 별. 지속 05d."
rows["225:620037770"]="즉시 바람을 불어넣고 타겟을 쏘아 올리는데, 피해가 없겠지만, 매술이 끊어지고 학교의 매술이 발사되지 않도록 하는 것 또한 위협을 낮추는 것이고, 적이 공격할 확률도 낮게 만듭니다."
rows["226:1185544861"]="야드 안에 있는 사냥꾼과 침습 멤버들은  ⁇ 타의 무리의 모습을 갖추고, 움직임을 증가시키는 속도입니다. 이 측면의 영향으로 부딪히면 한 번에 하나의 측면만 활동할 수 있다는 것을 알게 될 것입니다."
rows["226:208921527"]="증가 극대화 당신의 파괴적인 능력의 기회 그리고 당신의 파괴적 또는 복수능이 손상을 당하면 Shield Slam 능력의 냉각을 신선하게 할 수있는 기회가 있습니다 27d."
rows["226:476722130"]="월킨 형태로 공격하는 것은 당신이 미련하게 될 기회를 가지고 있습니다. %로 피해를 증가시켜, 균형을 맞추는 마법과 기지를 회복시키는 동안 반격에 면역력을 갖게됩니다. 마나 모든 초. 91d."
rows["227:980125017"]="당신의 그림자 볼트 주문이 만든 피해를 %로 증가시키고, 당신의 그림자 볼트는 당신의 목표물을 마법 손상에 취약하게 만들 수있는 기회를 가지고 있습니다. 효과에 의해 그 목표에 대한 마술 극대화의 확률은 증가합니다 00d."
rows["228:1671638046"]="사용에 관한 능력 (랭크 2) 을 가르칩니다.\010\010|cFFFFCC00 권한:|r\010|cFFFFFFFF급 2|r\010주문력을 |cffFF99002|r로 증가시킵니다.\010당신의 치유를 증가시킵니다 주문력 |cffFF99002|r.\010전투력을 |cffFF99002|r로 증가시킵니다."
rows["228:1857252425"]="사용에 관한 능력 (랭크 1) 을 가르칩니다.\010\010|cFFFFCC00 권한:|r\010|cFFFFFFFF급 1|r\010주문력을 |cffFF99001|r로 증가시킵니다.\010당신의 치유를 증가시킵니다 주문력 |cffFF99001|r.\010전투력을 |cffFF99001|r로 증가시킵니다."
rows["228:551573422"]="< 글씨 한 편의 간편자 조각. 몇 마디는 읽을 수 있고, 그 밖엔 거의 없다. >\010\010불이 노예화된 시대는 다시 돌아갈 수 있고, 우리도 해방될 수 있습니다. 불꽃은 여전히 그들의 전 주인의 생각만으로 공포로 깜빡인다."
rows["229:1376861724"]="무작위 스킬 카드가 포함되어 있으며, 명성 동안 또는 새로운 캐릭터에서 레벨 1에서 사용할 수 있습니다.\010\010재능기부 카드는 특정 주문을 작성할 수 있도록 보장합니다.\010\010재능기부 카드는 시라스 다크문에서 수도권에서 얻습니다."
rows["229:1411495517"]="얼음 함정이 설치되어 첫 번째 적이 접근할 때 자신을 둘러싼 얼음 슬라이드를 만들어냅니다. 야드 내 모든 적은 효과 영역에있을 때 느려집니다. 함정이 존재합니다. 한 번에 하나의 함정이 활성화 될 수 있습니다."
rows["229:1806772445"]="캐스터의 발에 건강이 있는 분노의 토템을 불러 일으킨다. 토템은 모든 당과 습격 구성원들에 대해 주문력 증가하고, 야드 내 모든 적에 대한 모든 공격의 극대화 기회를 높인다."
rows["229:821957210"]="@세계벼림@나는 어떤 철학과도 속하지 않는다는 것을 고백합니다. 나는 실제 세계와도 속합니다. 현실은 어떤 이데올로기에도 맞지 않기 때문입니다. 그러한 것들은 추상화, 우리가 답의 약속 없이 질문을 던질 두려움으로 받아들이는 편안함입니다."
rows["229:826694455"]="당신의 유해한 심판 주문은 10 당원 또는 파격 멤버 마나 재생에 최대 1%의 대 한 그들의 최고 마나 d에 대한 5 초, 그리고 즉시 당신이 당신의 기지를 부여 할 수있는 기회를 가지고 있습니다 마나."
