rows["22:986624634"]="해조의 하로"
rows["230:1118935863"]="1에 대해 친근한 목표를 치유하고, 그 다음 인근의 추가 목표물을 치료하기 위해 뛰어납니다. 당원 한 명에게 투입되면, 치유는 다른 당원에게만 뛰어들게 됩니다. 각 도약은 치료의 효과를 40%로 감소시킵니다."
rows["230:1220237427"]="증가 극대화 %로 치면 가능성은 증가하고, 잠시 동안 가만히 있으면 스나이퍼 훈련을 받게 되는데, 18d."
rows["230:1220254588"]="증가 극대화 %로 치면 가능성은 증가하고, 잠시 동안 가만히 있으면 스나이퍼 훈련을 받게 되는데, 19d."
rows["230:1222348230"]="증가 극대화 %로 치면 가능성은 증가하고, 잠시 동안 가만히 있으면 스나이퍼 훈련을 받게 되는데, 20d."
rows["230:284717168"]="당신의 그림자 단어: 고통, 마인드 플레 및 뱀파이어 터치 매력은 또한 지속 가능한 d에 의해 해로운 매술의 기회를 증가시키고, 당신의 마인드 블라스트, 마인드플레 및 마인드 세어 매술에서 얻은 주문력의 이익을 증가시킵니다."
rows["230:37425922"]="적에 대한 얼음 불의 번개를 발사하여 얼음 불의 손상을 일으켜 이동 속도를 늦추고 추가 얼음 불의 피해를 일으킨다"
rows["230:433211192"]="디스펜서는 다음과 같이 작용한다.\010기로마틱 마이크로 조절기\010아크라이트 스펜어\010금속 해머,\010광산 픽\010스킨닝 칼\010목재축\010가상 잉크 세트\010철학자 돌\010\010|cffFF0000이 항목이 파괴되면 모든 업그레이드가 손실됩니다!|r"
rows["230:43863714"]="또한 방어적 자세 (Rank 1 보다 효과적) 에 있을 때 혈관 갈증과 사망 공격 능력으로 인해 발생하는 위협을 크게 증가시킵니다."
rows["230:43880875"]="또한 방어적 자세 (Rank 2 보다 효과적) 에 있을 때 혈관 갈증과 사망 공격 능력으로 인해 발생하는 위협을 크게 증가시킵니다."
rows["230:961565781"]="이 산이 날 수 있는 방법을 가르쳐줍니다\010\010하이마운틴의 언덕에 사는 가장 따뜻한 종 중 하나인 이 동물은 가장 힘든 상황에서도 살아남을 수 있는 의지로 인해 매우 인기 있는 동반자입니다."
rows["231:1864455267"]="이 불꽃 은 악성 불꽃 의 불꽃 으로 부터 가져온 것 이며, 그 가 자신 의 마음 을 가지고 있는 것 처럼 일정한 지 없이 짝짓게 하고 있으며, 부드럽게 박스 를 받으며 발화 될 만한 모든 것 을 불태워버리기 위해 갈망 하는 것 이다."
rows["231:1946087932"]="당신 을 막는 것 은 죽음 이 그 자체 처럼 힘들어집니다. 당신 에게 사용 된 모든 스턴 및 공포 효과 의 기간 은 20% 로 줄어들며, 당신 의 탑승 속도는 20% 로 증가 합니다. 이것은 다른 운동 속도 증가 효과 와 함께 쌓이지 않습니다."
rows["231:995687354"]="당신은 얼음 블록에 갇혀있어 모든 물리적 공격과 d의 주문으로부터 보호되지만 그 동안 공격하거나 움직일 수 없습니다. 또한 Hypothermia를 유발하여 25d의 얼음 블록을 재탄생시키는 것을 막습니다."
rows["232:15318795"]="부패의 마법으로 피해를 처리하면, 당신은 즉시 손상된 피해를 치유합니다. 또한, 당신의 부패, 부패의 씨앗과 불안정한 고통의 손상이 시간이 지남에 따라 증가합니다."
rows["232:1581467036"]="수호자의 벼룩 의 부드러운 흔들림 은 공기 자체 를 진동 하게 해 준다. 단단 한 표면 에 충돌 하면 다른 잠든 존재 를 깨우칠 수 있는 공명 이 발발 될 것 이다."
rows["232:2133725405"]="당신의 부패와 불안정한 고통 매력은 보너스 매술의 손상을 추가로 얻으며, 당신의 Drain Life, Drain Soul, Shadow Bolt, 그리고 Haunt 매술은 목표에 대한 부패 매술의 기간을 재설정할 기회를 갖게됩니다."
rows["232:604393398"]="엔드게임 마나스타머스에서 얻은 |cffFFFFFF수준 226 레벨 256.|r\010\010|cFFffffff내용:|r \010\010+ 정상적인 카라잔 기어\010\010|cFFffffff 포함 가능성은:|r\010\010+ 영웅적인 카라잔 기어\010+ 영웅적인 그루스의 래어 기어\010+ 영웅적인 던전 기어"
rows["232:666879333"]="엔드게임 마나스타머스에서 얻은 |cffFFFFFF수준 136 레벨 166.|r\010\010|cFFffffff내용:|r \010\010+ 정상적인 카라잔 기어\010\010|cFFffffff 포함 가능성은:|r\010\010+ 영웅적인 카라잔 기어\010+ 일반  ⁇ 루의 래어 기어\010+ 영웅적인 던전 기어"
rows["232:677354257"]="캐스터의 발에 건강이 있는 분노의 토템을 불러 일으킨다. 토템은 모든 당과 공격 구성원들에 대해 주문력 증가하고, 야드 내 모든 적들에 대한 모든 공격의 극대화 기회를 높인다."
rows["233:1396139052"]="이 동행자를 불러내는데 어떻게 해야 하는지 가르쳐줍니다 불타는 군단이 미니 지옥은 그 기원에 대한 어둠을 거부하고 따뜻한, 편안한 빛을 발하는 것을 선호합니다.\010\010이건 전투가 아닌 동반자입니다."
rows["233:14408739"]="여행 형태 또는 모양이 바뀌지 않은 동안 천과 가죽의 추가 장갑을 제공하여 Barkskin 주문으로 인한 손상을 줄이고 Barkskin가 분해되는 가능성을 감소시킵니다."
rows["233:1599112673"]="투테마는 모든 당원 및 습격 구성원에게 주문력을 증가시키고, 야드 내 모든 적에 대한 모든 공격의 극대화 기회를 증가시킵니다."
rows["233:1914305809"]="@|cFFCC0000피가 갈라진|r@그 아래 스컬지 부패는 당신이 희미한 표기판을 만들 수 있습니다: ...이 통일된 목소리로 나와 함께 울라 리치 왕 자기 자신을 위해! 얼라이언스 그리고 카즈 모단에게!"
rows["233:274108968"]="야드 내의 당원들로부터 받은 모든 손해가 팔라딘으로 (팔라딘의 건강의 최대량에 따라 당원들의 수를 곱하기) 전환된다."
rows["233:896365357"]="카인 가족 의 표지판, 한때 가문의 여자 들 의 손가락, 목, 귀 를 장식 한 많은  ⁇ 들 중 하나. 특히 이 사람 을 데리고 도망치려고 한 하녀 는 지붕 에 뛰어내리긴 했지만 그 괴물 은 더 빨리 있었다."
rows["234:1816728846"]="위험성이 높은 경우 사망에 빠지지 않습니다.\010\010고위험 언고로, 불타는 스텝스 및 아즈샤라에서 발견된 코어  ⁇ 이 된 짐승들의 거리를 열면 '노 리트리트' 디버프를 유발하여 탈출 마법을 통해 안전으로 이동하지 못하게 됩니다."
rows["234:780007354"]="적의 목표물을 명상 상태에 놓아, d까지 무력화하고 정의로운 복수의 효과를 제거합니다."
rows["234:847929514"]="@Dungeoneer@ 영웅적 던전 기어를 포함하는 업그레이드 된 전쟁 포, 주로 현재의 주요 통계에 대한 장비 업그레이드를 중심으로. \010\010이 전쟁 포는 PvE 일간 탐사에서 얻었고 탱크에 대한 보너스 포로 기회를 가지고 있습니다."
rows["235:631645292"]="@Classic@ 최대 레벨을 열어야 하며, 다음을 포함합니다:\010 - 레벨이 공개될 경우 1개 이상의 글로벌 계층 토큰의 가능성이\010 - 4에서 6까지의 장비 조각들은 현재 레벨 습격이나 던전에서 나온다.\010 - 당신 선택의 클래스에 한 전설적인 마법사"
rows["236:1169582099"]="위험성이 높은 경우 사망에 빠지지 않습니다.\010\010고 위험성 장그라마르쉬, 테로카르 숲 및 나가란드에서 발견된 트와스트한 숨겨진 캐시를 열면 '노 리트리트' 디버프를 유발하여 탈출 마법을 통해 안전으로 이동하지 못하게 됩니다."
rows["236:2022220618"]="< 글씨 한 편의 간편자 조각. 몇 마디는 읽을 수 있고, 그 밖엔 거의 없다. >\010\010쉐도우버런 기일은 길을 알고 오직 아치워록만이 우리 족속을 굴욕으로부터 해방시킬 수 있어"
rows["236:265248453"]="수면으로 변신하여 수영 속도를 높이고 드루이드가 물 아래에서 호흡할 수 있게 해주는 역할을 합니다. 또한 폴리모프 효과로부터 캐스터를 보호합니다.\010\010형태를 바꾸는 행위는 폴리모프와 운동에 영향을 미치는 효과를 방출합니다."
rows["237:1066049835"]="위험성이 높은 경우 사망에 빠지지 않습니다.\010\010High-Risk Blade의 Edge Mountain와 Shadowmoon Valley에서 발견된 Dread Hidden Cache를 열면 No-Retreat 디버프를 유발하고, 탈출 마법을 통해 안전으로 이동하지 못하게 됩니다."
rows["238:1722919419"]="무작위 골든 럭키 스킬 카드가 포함되어 있으며, 명성 동안 레벨 1 또는 새로운 캐릭터에서 활성화 될 수 있습니다.\010골든 럭키 스킬 카드는 특정 주문을 작성할 확률을 크게 증가시킵니다.\010\010이 물건은 실라스 다크문에서 골드로 샀어"
rows["238:222994804"]="엔드게임 마나스타머스에서 얻은 |cffFFFFFF수준 316 레벨 346.|r\010\010|cFFffffff내용:|r \010\010+ 영웅적 계층 4 기어\010\010|cFFffffff 포함 가능성은:|r\010\010+ 신화 카라잔 기어\010+ 미딕 그루스의 래어 기어\010+ 미딕 던전 던전 기어"
rows["239:149098948"]="표적된 목표에 의해 당신의 총과 애완 동물의 특수 능력에 의한 피해를 증가시키고, 극대화의 손해 보너스를 증가시킵니다."
rows["239:1672460384"]="비행 형태로 모양을 변경하여 이동 속도를 높이고 비행할 수 있습니다. 전투에서 사용할 수 없습니다. 이 형태를 아웃랜드 또는 노스렌드에서만 사용할 수 있습니다.\010\010형태를 바꾸는 행위는 폴리모프와 운동에 영향을 미치는 효과를 방출합니다."
rows["239:33589453"]="무장과 얼음 저항을 증가시킵니다 적이 캐스터를 공격하면 그들의 움직임이 느려지고 공격 사이의 시간이 증가할 수 있습니다"
rows["239:851437265"]="톱과 휘둘러지는 뿌리로부터의 피해는 증가하고, 트레언트에서 발생한 피해는 증가합니다. 또한, 바르크스킨이 활성화된 동안 트레언트로부터의 피해와 공격은 3 세커를 목표로 할 수있는 기회를 가지고 있습니다."
