rows["240:1908195325"]="죽음의 기사 는 얼음 이 존재 하 고 % 체력 증가, 옷, 가죽, 우편 및 판 의 유갑 기조 % 를 차지 하고 위협이 발생 하는 위험 을 감소 합니다. 한 번에 오직 한 명 만 활동 할 수 있습니다."
rows["240:491980004"]="세계에서 발견되는 미스틱 제단에서 사용되거나 수도권에서 미스틱 매춘자를 적용하기 위해 소집됩니다.\010\010미스틱 오브에 대해 더 많은 것을 배울 수 있는 방법은 미스틱 알터 또는 승천의 길: 레벨에서 힘과 신비한 추출을 찾는 것 60를 따라가면 된다."
rows["241:1194465520"]="치유파, 작은 치료파 또는 리프타이드로 심사적으로 치유되면 조상 영을 불러서 도움을 주며 40 치료된 금액의 매출에 대해"
rows["241:1568178622"]="시간이 지남에 따라 손상을 일으키는 마무리 동작, 전투력으로 증가합니다.\010   1 점: 초에 의한 손해\010   2 점: 초에 대한 손해\010   3 점: 초에 대한 손해\010   4 점: 초에 대한 손해\010   5 점: 초에 대한 손해"
rows["241:1603966302"]="뱀의 측면 - 원숭이의 손해배상을 줄인다 - 호크가 활동하면서 당신에게 해를 줄인다 - 드래곤호크의 전투력 보너스를 증가시킵니다 - 원숭이와 호크의 측면에서 보너스를 결합합니다."
rows["241:2084276368"]="당신의 정신 폭발과 그림자 단어: 죽음 비판적 공격은 100% 확률과 당신의 미인 플레이 비판적 공격은 50전체 정신을 증가시킬 확률 % 마나 캐스팅 중 재생속률을 높일 수 있습니다. 94d."
rows["241:2121383253"]=" ⁇ 식물 이 가장 큰 식물 이 되고, 뿌리가 어쩔 수 없이 방해 를 받을 만한 곳 으로까지 도달 합니다. 그 의 불순종 한 마음 을 이루는 악성 씨앗 이 파멸 될 때까지, 무서운 카니바루즈는 계속 자르고 번영 할 것입니다."
rows["241:255161557"]="소울스톤은 목표물의 영혼을 저장하는 데 사용될 수 있습니다. 목표물이 그의 영혼이 저장되는 동안 사망하면 그는 건강하고  마나.\010\010거짓된 물건은 15분 이상 로그오웃되면 사라진다."
rows["241:775427097"]="Druid가 각종 형태 변화의 범위 내에서 지속되는 효과를 제공합니다.\010\010곰 형태 - 형태에 의해 증가 물리 피해 - 형태에 의해 확률을 증가 극대화 - 생명체에 의한 주문 손상으로 증가 - 치유를 증가시킵니다 ."
rows["242:1078611021"]="이 형태로 당신의 갑옷이 % 증가하고 더 많은 피해를 입게 되고, 스턴트 및 함정 효과의 기간은 줄어들게 되는데, 당신은 정상적인 능력 외에도 몇 가지 독특한 악마 능력을 얻게 됩니다. 3 잠깐 차갑게"
rows["242:2042293643"]="곰 형태 또는 디레어 베어 형태로 분노 능력을 사용하는 동안, 당신의 손상은 %로 증가하고 호랑이의 화력 능력 또한 즉시 에너지를 회복합니다. 또한, Bear Form, Cat Form 및 Dire Bear Form의 비용은 마나 로 감소합니다."
rows["243:1047724284"]="악마의 영혼 돌을 만들 수 있습니다. 그 영혼 돌은 목표물의 영혼을 저장하는 데 사용될 수 있습니다. 목표물이 그의 영혼이 저장되는 동안 사망하면, 그는 건강하고  마나.\010\010거짓된 물건은 15분 이상 로그오웃되면 사라진다."
rows["243:1570041840"]="당신의 냉기 피해 마법을 통해 겨울의 추운 효과를 적용할 수 있는 기회를 더해줍니다. 이는 스택스까지의 시간으로 마법을 통해 목표물을 심하게 타격할 확률을 높여줍니다."
rows["243:980740228"]="더 큰 영혼 돌을 만들 수 있습니다. 그 영혼 돌은 목표물의 영혼을 저장하는 데 사용될 수 있습니다. 목표물이 그의 영혼이 저장되는 동안 사망하면, 그는 건강하고  마나.\010\010거짓된 물건은 15분 이상 로그오웃되면 사라진다."
rows["244:1044102932"]="대상 동물 에 대한 정보 를 수집 하십시오. 도구 팁 은 손상, 건강, 장갑, 특별한 저항 및 식습관 을 표시 할 것 이다. 또한, 야구학 은 생물 의 숙화 가능 여부 와 숙화 된 생물 의 능력 을 알려 줄 것입니다."
rows["244:1124961186"]="팔라딘은 d에 대한 신성한 지혜로 가득 차 있어, 각 승전 공격에 팔라딘의 최대 마나을 회복할 기회를 제공합니다.\010\010이 봉사의 에너지가 풀리면  신성 피해 적에게"
rows["244:1155831938"]="위험성이 높은 경우 사망에 빠지지 않습니다.\010\010장그라마르쉬, 테로카르 숲, 나가란드에서 발견된 휘어진 짐승들의 거리에 유인하는 생물. 먹이를 넣으면 피난 마법을 통해 안전으로 이동하지 못하게 됩니다."
rows["244:2117399186"]="무력 공격은 자동으로 무력 공격에서 독을 표적에 적용합니다. 느린 무기들은 더 많은 에너지를 필요로 합니다. 극대화- 상 1 복합점"
rows["244:925106315"]="목표지에 얼음 함정을 배치하는 얼음 화살기를 발사하여, 접근하는 첫 번째 적을 얼어붙여 모든 행동을 방지합니다."
rows["245:2072063915"]="이 시간의 유적은 아제로스의 더 큰 존재들을 불러모으키기 위해 사용된다.\010\010파티에 참여하고, 적어도 집회를 3 영웅들마다 시간의 유적들을 가지고 위대한 존재들의 성소리로 데려가 그들을 불러올 것입니다."
rows["245:2140638629"]="위험성이 높은 경우 사망에 빠지지 않습니다.\010\010스컬지 고 위험 서부 전염병 및 동부 전염병 지역에서 발견 된 숨겨진 캐시를 열습니다. 캐시를 열면 No-Retreat 디버프를 유발하여 탈출 매력이 당신을 안전하게 데려가는 것을 방지합니다."
rows["245:254572403"]="또한, 혈액 스트라이크 또는 전염병으로 타격할 때마다 혈액 룬이 활성화되면 죽음의 룬이 될 가능성이 있습니다."
rows["246:1068981546"]="스피프트멘드, 재성장, 영양 또는 치유 터치 주문으로 목표를 비판적으로 치료하면 치료된 금액에 대한 살아있는 씨앗을 목표물에 심는 기회가 있습니다. 04d."
rows["246:1494625328"]="만약 당신이 함께 싸우는 무기로 피해를 입히면, 당신은 2) 다음 번개 발사, 체인 라이트닝, 작은 치유 파동, 치료 파동, 체인 치유 또는 스택에 의해 Hex 주문의 cast 시간을 줄이기 위해 5 시간, 시간 17d."
rows["246:1630084537"]="d를 위해 적을 판단하는 봉사의 에너지를 풀어주고, 도망하지 못하게 하고 이동 속도를 제한한다. 추가 판단 효과를 얻기 위해 개별 봉사를 참조하십시오."
rows["246:1708786773"]="만약 당신이 함께 싸우는 무기로 피해를 입히면, 당신은 4) 다음 번개 발사, 체인 라이트닝, 작은 치유 파동, 치료 파동, 체인 치유 또는 스택에 의해 Hex 주문의 cast 시간을 줄이기 위해 5 시간, 시간 17d."
rows["246:313802782"]="만약 당신이 함께 싸우는 무기로 피해를 입히면, 당신은 1) 다음 번개 발사, 체인 라이트닝, 작은 치유 파동, 치료 파동, 체인 치유 또는 스택에 의해 Hex 주문의 cast 시간을 줄이기 위해 5 시간, 시간 17d."
rows["246:358986024"]="엔드게임 마나스타머스에서 얻은 |cffFFFFFF수준 166 레벨 196.|r\010\010|cFFffffff내용:|r \010\010+ 영웅적인 카라잔 또는 영웅적인 그루일의 래어 기어\010\010|cFFffffff 포함 가능성은:|r\010\010+ 정상 마그테리돈의 래어 기어\010+ 미딕 던전 던전 기어"
rows["246:527964227"]="만약 당신이 함께 싸우는 무기로 피해를 입히면, 당신은 3) 다음 번개 발사, 체인 라이트닝, 작은 치유 파동, 치료 파동, 체인 치유 또는 스택에 의해 Hex 주문의 cast 시간을 줄이기 위해 5 시간, 시간 17d."
rows["246:834682357"]="@|cffff0000Bronzebeard 영역은 이제 모든 사람들에게 자유롭게 액세스 할 수 있습니다.@이 항목은 이제 제한된 버전의 수집품입니다. 창업자가 원래 9 클래스의 알파 - 브론즈베어드 영역에 접근을 허용하기 위해 서버 출시 전에 사용했습니다."
rows["246:954767108"]="엔드게임 마나스타머스에서 얻은 |cffFFFFFF수준 256 레벨 316.|r\010\010|cFFffffff내용:|r \010\010+ 영웅적인 카라잔 또는 영웅적인 그루일의 래어 기어\010\010|cFFffffff 포함 가능성은:|r\010\010+ 정상 마그테리돈의 래어 기어\010+ 미딕 던전 던전 기어"
rows["247:1007444040"]="<약품은 완성되지 않았습니다. 옆에는  ⁇ 스키네아가 이미 구매한 재료와 아직 구입할 수 없는 성분들을 나열하고 있습니다."
rows["247:1441152599"]="당신의 성 충격 비판적 타격은 다음 빛의 플래시의 캐스팅 시간을 세컨으로 줄여줍니다 또는 다음 빛의 중요한 기회를 증가시킵니다. 또한, 당신의 빛의 플래시가 추가로 22d에 대한 성 கேட지와 목표를 치유하도록 만듭니다."
rows["247:2045855186"]="이 은유적 인 유물 은 저렴한 카니발 상점에서 발견 될 것 이라고 생각 할 수 있습니다. 하지만 이 유물 은 그  ⁇ 한 외모 와도 자신 의 의지 로 울부짖습니다. 바다 에 대한 반향 을 담고 있는 해수름처럼, 이 결정 구구는 듣기 위해 용기를 기울이는 마음 에게 고소 합니다."
rows["247:355133632"]="알'아르는 카엘'타스 선스트라이더의 소중한 애완 동물인 피닉스 입니다. 그는 깊이 돌보아주십니다. 그의 자녀들도 카엘'타스에 봉사합니다. 모든 피닉스와 마찬가지로, 그는 되살아난 자 자신의 먼지로부터 태어났기 때문에 그를 추락하고자 하는 모험가들은 한 번 이상 그렇게 해야 할 수도 있습니다. . . ."
rows["247:578883848"]="플래시 치유, 더 큰 치유, 그리고 회개 주문은 표적을 은혜로 축복할 기회를 가지고 있습니다. 이 효과는 3까지 쌓이게 될 것입니다."
rows["247:599035239"]="드루이드의 피부는 껍질처럼 단단하게 된다. 모든 피해가 보호되는 동안 감소한다, 손상적인 공격은 마법을 보내는 지연을 유발하지 않을 것입니다. 이 마사는 놀라서, 얼어붙고, 무력, 두려워하거나 잠자리에있을 때 사용할 수 있습니다. 모든 형태로 사용 가능합니다."
rows["248:1915510705"]="이 지역을 뒤흔든 재앙이 일어나기 전에 죽게 된 트롤의 고골이 지쳐졌어요. 그 후에 온 사람들은 잠자리의 소음과 유혹적인 호소로 착각했습니다."
rows["248:837766786"]="코스메틱 무기의 세트 (Cosmetic Weapon Set) 는 트랜스모그리피케이션으로 사용되도록 되어 있습니다. 1 아쉬 인카네이션은 다른 플레이어, 경매소 또는 잃어버린 가게에서 얻을 수 있습니다."
rows["249:1054676600"]="@세계벼림@신화는 한 번씩 달이 가득한 순간, 번개가 시계처럼 타격하는 단독의 봉우리라고 합니다. \010\010막대기의 나무는 한 번은 아니라 두 번이나 타진 나무에서 가져온 것입니다. 이제 그 힘이 오래전 잃어버린 Thunderfalls 가문의 이 유물으로 엮여 있습니다."
rows["249:248560865"]="밀하우스 마나폭풍의 프로토타입은 마나폭풍에서 길을 열어, 당신이 생각하는 방식으로 재조립되어 올바른 것 같습니다. 밀하우스는 그가 마나폭풍에 보내는 사람들을 쉽게 끌어낼 수 있지만, 아마도 그러한 장치에 대한 다른 필요성을 찾을 것입니다."
