rows["250:1327521596"]="무작위 재능 황금 기술 카드를 포함하고 있으며, 명성 동안 레벨 1 또는 새로운 캐릭터에서 사용할 수 있습니다.\010\010재능 골든 스킬 카드는 특정 주문을 작성할 수 있도록 보장합니다.\010\010재능의 골든 스킬 카드는 수도 시라스 다크문에서 얻습니다."
rows["250:135136451"]="명성 기간 동안 또는 새로운 캐릭터에서 레벨 1에서 사용할 수 있는 무작위 능력 기술 카드 5을 포함합니다.\010\010능력 기술 카드 는 특정 능력을 작성하는 것을 보장합니다.\010\010능력 카드 패키지는 주로 수도 시라스 다크문에서 얻습니다."
rows["250:1448968575"]="@세계벼림@Radiance Town의 열호가 착용한 헬름. 가까이 다가오는 사람들에게는 희미한 지침이 퍼집니다. 신조 ⁇ 의 기원은 감싸여 있지만, 일부에서는 방사능의 신에 대한 속삭임이 있습니다. 그는 그의 광대 Majesty 앞에 나타나 그에게 신성한 목적을 부여했습니다."
rows["250:483650865"]="시엘 주문의 에너지를 방출하여 적을 d로 판단하여 공격자의 기지를 회복할 기회를 제공합니다. 마나- 추가 판단 효과를 위해 개별 봉사를 참조하십시오."
rows["251:1028308464"]="다신 보호가 되어있으면, 대상이 다시 신성 방패, 신성 보호 또는 보호 손으로 공격될 수 없습니다."
rows["252:1041316811"]="Druid의 손상, 치유 마술 및 자동 공격의 각은 캐스터가 클리어캐스팅 상태에 들어갈 수있는 기회를 가지고 있습니다. 클리어캐스팅 상태는 다음 손해, 치유 마술 또는 공격 능력의 마나, 분노 또는 에너지 비용을 70s1%로 줄입니다."
rows["252:147326257"]="모든 주문 손상을 회전하고 침묵 효과의 기간을 감소시키는 룬 총으로 한 손으로 사용하는 룬 무기를 부착합니다. 추가적인 침묵 기간 감소와 함께 누적되지 않습니다."
rows["252:191270249"]="농축 아우라의 효과를 추가로 증가시키고, 어떤 아우라는 활성임에도 불구하고 영향을 받은 그룹 구성원에게 사용되는 침묵이나 중단 효과의 기간을 감소시킵니다."
rows["252:28161619"]="고양이 모양으로 변신하여, 짝짓기를 증가시킵니다. 전투력 더하기 민첩성또한 포미를 폴리모프 효과로부터 보호하고 다양한 고양이 능력을 사용할 수 있습니다.\010\010형태를 바꾸는 행위는 폴리모프와 운동에 영향을 미치는 효과를 방출합니다."
rows["253:1806164040"]=" ⁇ 터에 fel 에너지로 둘러싸고, 증가 주문력 더 추가로 주문력 또한, 당신은 당신의 최대의 건강을 회복합니다 5 단 한 종류의 갑옷 마법을 만 매번 마법사에서 사용할 수 있습니다"
rows["253:944863804"]="@세계벼림모리거 호로우하프는 어린 시절부터 그를  ⁇ 고 있었고, 그 사이에 몇 년이 있었음에도 불구하고, 그녀는 그를 그의 부친으로 주장하려고 음모를 꾸미며, 언젠가 아버지를 향해 그를 몰아넣을 수 있기를 바랬습니다. 그녀는 그랬습니다. 그리고 그는 죽었다."
rows["254:1623528401"]="위험성이 높은 경우 사망에 빠지지 않습니다.\010\010스컬지 고 위험 높은 서부 전염병 및 동부 전염병 지역에서 발견 된 가짜 짐승 둥지를 열습니다. 캐시를 열면 No-Retreat 디버프를 유발하여 탈출 매술이 당신을 안전하게 데려가는 것을 방지합니다."
rows["254:851171459"]="목표물은 60 야드 반경 내에 있는 모든 멤버에게 빛의 Beacon가 됩니다. 당신이 팀 또는 공격 회원들에게 던지는 모든 치유는 또한 치료된 금액에 대한 Beacon를 치유합니다. 한 번에 하나의 목표만이 빛의 Beacon이 될 수 있습니다."
rows["255:1544280372"]="잔인한  ⁇ 의 주인이자 파괴자 마너로스의 종인 마그테리돈은 그 재앙 이후 드레노르로 가는 길을 찾았다."
rows["255:1607403427"]="이 신비로운 전사들은 의식적으로 맹목화되어 '스펙트럼 시력'을 개발하여 악마와 죽은자를 더 명확하게 볼 수 있도록"
rows["255:2002698789"]="강력한 그루알의 지도 아래, 그론과 그들의 오그르 종들은 숫자가 적어졌던 검은 용 보호자들이 감당할 수 없을 정도로 많은 것을 증명했습니다. 거의 모든 드래곤은 블라데스파이어 가문의 악마적 마법에 의해 하늘에서 찢겨졌고"
rows["255:272263544"]="당신이 60 수준에 도달했을 때 당신의 저장된 8 능력 본질을 두 단계 50 및 60 재능에 사용할 수 있습니다! 당신은 단지 1 레벨 60 재능을 선택할 수 있습니다. 이 상자는 당신이 선택한 50 및 60 재능을 배워 새로운 것을 선택 할 수있는 재능을 담은 Dice."
rows["255:459861870"]="고생혈이  ⁇ 은 목걸이가, 한때 케인 가문의 사냥개에 속해 있었다. 집의 주인이 그의 옆에서 휘어풀리는 숲을 사냥할 때까지, 그들은 깨어있는 눈을 가진 검은 염소를 만났던 날까지."
rows["255:741291590"]="고고생족은 고대 칼도레이 문명의 상류 계급이었으며, 처음에는 밤의 엘프들로 구성된 이름 없는 계층으로, 특이한 지능, 힘, 기술 또는 부를 가지고 있었고, 따라서 지배하는 군주에게 호의를 얻었다."
rows["257:1357208492"]="피가 만들어져 PvP 기어로 변합니다.\010\010이 경우 PvE 전력을 제거하고 PvP 전력으로 대체합니다.\010\010만약 당신이 Bloodforging 영웅, 신화 또는 상승한 아이템이라면 그들은 정상적인 Bloodforged 버전으로 변환됩니다\010\010조심해, 이건 돌이킬 수 없는 일이야."
rows["258:1969037854"]="비상할 수 없는 아름다움의 반지, 천지빛의 색인 사피르로 장식되어 있다. 세레니아 여인은 두 번 사망했다. 첫째는 로데론에서 스컬지의 손에, 그리고 다시 스카데알드로 돌아왔을 때."
rows["258:2030516469"]="아래로 가는 손해 35건강은 %로 감소한다. 또한, 만약 당신이 죽게 되는 경우, 당신은 최대 건강 (방위에 따라 치유된 금액) 에 의해 치료될 수 있습니다. 33d."
rows["259:313440675"]="1 활과 1 화살 인자네이션을 포함하는 화장품 무기 세트. \010\010이 제품은 Transmogrification와 함께 사용되도록 되어 있습니다. 당신은 Vanity 컬렉션에서 화장품 세트가 어떻게 보이는지 볼 수 있습니다. 다른 플레이어, 경매소 또는 잃어버린 가게에서 얻을 수 있습니다."
rows["259:317246325"]="만약 당신이 사망할 경우, 당신의 최대의 건강의 10%로 줄일 확률이 높다. 또한, 모든 피해는 최대 90%로 감소될 수 있습니다. (탄력으로 수정) 이 효과는 분당 한 번 이상 발생하지 않습니다."
